-- =============================================================================
-- 437 — LE CAHIER D'EXERCICES DE TLE (partie 2)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 437 --niveau Tle --matieres espagnol,llcer-anglais --suffixe 2 > supabase/contenu/437_exercices_tle_2.sql
--
-- 99 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   espagnol.k149           36 exercices · 12 chapitres
--   llcer-anglais.k167      33 exercices · 11 chapitres
--   llcer-anglais.k168      30 exercices · 10 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('c033cd1a-45a2-5ecf-9daa-00196389b5b2'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un bulo dans le groupe de la famille","competence":"comprendre-langue","situation":"Carmen, la grand-mère de Lucía, vient de recevoir un message alarmant sur son téléphone. Lis leur conversation : que fait Lucía avant de le transférer ?","documents":[{"id":"sms1","type":"dialogue","modele":"sms","titre":"Mensajes de la familia","participants":[{"nom":"Carmen","emoji":"👵","cote":"gauche"},{"nom":"Lucía","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Carmen","texte":"¡Importante! Dicen que mañana cortarán internet tres días en todo el país. ¡Reenvíalo a toda la familia!"},{"qui":"Lucía","texte":"Abuela, eso suena a bulo. Antes de reenviarlo, voy a contrastarlo en Maldita.es."},{"qui":"Lucía","texte":"Ya está: lo han desmentido. No hay ningún corte previsto."},{"qui":"Carmen","texte":"¡Menos mal! ¿Y cómo lo sabías?"},{"qui":"Lucía","texte":"Nadie firma el mensaje, no cita ninguna fuente y te mete prisa para reenviarlo."}],"source":"SMS écrits pour l’exercice"}],"questions":[{"enonce":"Que fait Lucía avant de transférer le message de sa grand-mère ?","aide":"Relis la deuxième réplique de Lucía : que va-t-elle faire « antes de reenviarlo » ?","type":"choix","options":[{"id":"a","texte":"Elle transmet aussitôt le message à toute sa famille"},{"id":"b","texte":"Elle supprime l’application de messagerie de sa grand-mère"},{"id":"c","texte":"Elle vérifie l’information sur un site de vérification des faits"},{"id":"d","texte":"Elle demande à un journaliste d’écrire un article sur le sujet"}],"multiple":false},{"enonce":"Dans la dernière réplique de Lucía, touche les trois mots qui révèlent un bulo : l’auteur absent, la preuve absente et la pression exercée.","aide":"Cherche ce que personne ne fait (signer), ce que le message ne donne pas (sa source) et ce qu’il impose (aller vite).","type":"zone","document":"sms1","multiple":true},{"enonce":"Associe chaque mot espagnol du document à son équivalent français.","aide":"« Reenviar » contient le préfixe re- : on envoie de nouveau.","type":"association","gauche":[{"id":"g0","texte":"el bulo"},{"id":"g1","texte":"contrastar"},{"id":"g2","texte":"desmentir"},{"id":"g3","texte":"reenviar"}],"droite":[{"id":"d0","texte":"recouper, vérifier"},{"id":"d1","texte":"démentir"},{"id":"d2","texte":"transférer"},{"id":"d3","texte":"la fausse nouvelle"}]},{"enonce":"Complète la phrase avec un verbe du vocabulaire du cours.","aide":"Un site de vérification ne fabrique pas et ne propage pas les fausses nouvelles.","type":"trous","segments":["Maldita.es sirve para ",0," las noticias dudosas."],"banque":["reenviar","contrastar","verificar","inventar"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["c"]},"explication":"Lucía va **contrastar** le message sur Maldita.es, un site de vérification : on vérifie avant de partager."},{"cle":{"type":"zone","ids":["m48","m54","m58"]},"explication":"Les trois signes : personne ne **firma** (pas d’auteur), aucune **fuente** (pas de preuve), et on te met **prisa** (la pression pour réenvoyer vite)."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"**Bulo** = fausse nouvelle ; **contrastar** = recouper ; **desmentir** = démentir ; **reenviar** = transférer un message."},{"cle":{"type":"trous","trous":[["verificar","contrastar"]]},"affichage":"verificar","explication":"Maldita.es sert à **verificar** ou **contrastar** les informations douteuses, pas à les inventer ni à les réenvoyer."}]$ex$::jsonb),
  ('c033cd1a-45a2-5ecf-9daa-00196389b5b2'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Du tuit à la place : quatre mouvements","competence":"analyser-texte","situation":"Un journaliste résume le rôle des réseaux sociaux dans quatre mobilisations du monde hispanique, puis nuance son propos. Lis son reportage jusqu’au bout.","documents":[{"id":"rep","type":"texte","genre":"article","titre":"¿Basta un clic?","blocs":["Las redes sociales han cambiado la manera de protestar. En España, el 15-M de 2011 se convocó sobre todo por internet y miles de «indignados» ocuparon la Puerta del Sol, en Madrid.","Cuatro años después, un solo tuit bastó en Argentina para lanzar #NiUnaMenos, y el movimiento cruzó el continente.","Antes, en 2012, unos estudiantes mexicanos habían difundido un vídeo: así nació Yo Soy 132. Y en 2019, en Chile, la subida del billete del metro encendió un estallido social que acabó en un proceso constituyente.","Pero un clic no basta. Convocar es fácil; mantener el compromiso, organizarse y negociar exige mucho más. Por una parte, las redes aceleran la movilización; por otra, no sustituyen el trabajo en la calle."],"source":"Reportaje imaginado pour l’exercice"}],"questions":[{"enonce":"Remets ces quatre mobilisations dans l’ordre chronologique, de la plus ancienne à la plus récente.","aide":"Cherche l’année de chacune dans le reportage : 2011, 2012, 2015, 2019.","type":"ordre","items":[{"id":"a","texte":"#NiUnaMenos en Argentine"},{"id":"b","texte":"15-M à Madrid"},{"id":"c","texte":"Yo Soy 132 au Mexique"},{"id":"d","texte":"Estallido social au Chili"}]},{"enonce":"Dans le dernier paragraphe, touche le mot qui annonce la nuance apportée par le journaliste.","aide":"C’est le tout premier mot du paragraphe : il oppose ce qui précède à « un clic no basta ».","type":"zone","document":"rep","multiple":false},{"enonce":"Quelle idée défend le dernier paragraphe du reportage ?","aide":"Relis la dernière phrase : « por una parte… por otra… ».","type":"choix","options":[{"id":"a","texte":"Les réseaux ne servent qu’à diffuser de fausses informations sur les manifestants"},{"id":"b","texte":"Les réseaux accélèrent la mobilisation sans remplacer l’action collective durable"},{"id":"c","texte":"Les réseaux rendent désormais inutile tout rassemblement dans la rue"},{"id":"d","texte":"La mobilisation en ligne garantit toujours des résultats politiques durables"}],"multiple":false},{"enonce":"Complète la phrase de conclusion, avec une tournure utile en expression orale.","aide":"Après « conviene », on attend un infinitif.","type":"trous","segments":["Conviene ",0," esta idea: las redes ayudan a convocar, pero no bastan."],"banque":["matiza","matizo","matizar","matizamos"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"ordre","ids":["b","c","a","d"]},"explication":"Ordre : **15-M (2011)**, **Yo Soy 132 (2012)**, **#NiUnaMenos (2015)**, **estallido social (2019)**. Attention : le reportage ne suit pas l’ordre des dates."},{"cle":{"type":"zone","ids":["m86"]},"explication":"**Pero** introduit la nuance : les réseaux aident à convoquer, mais cela ne suffit pas."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le journaliste oppose deux faces : les réseaux **accélèrent** la mobilisation, mais ne **remplacent pas** le travail dans la rue."},{"cle":{"type":"trous","trous":[["matizar"]]},"affichage":"matizar","explication":"« **Conviene matizar** esta idea » : après *conviene*, le verbe reste à l’infinitif."}]$ex$::jsonb),
  ('c033cd1a-45a2-5ecf-9daa-00196389b5b2'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La escuela digital de Valentina","competence":"analyser-document","situation":"Pendant la pandémie de 2020, Valentina a suivi les cours en ligne depuis son village. Croise son témoignage avec les mesures présentées dans le tableau.","documents":[{"id":"valentina","type":"texte","genre":"recit","titre":"Testimonio de Valentina","blocs":["Me llamo Valentina y tengo diecisiete años. Vivo en un pueblo de montaña, lejos de la ciudad.","Cuando cerraron el instituto en 2020, los profesores nos mandaron las tareas por internet. En mi casa solo hay un móvil para tres hermanos, y la conexión se corta cada vez que llueve.","Mi amiga Clara, que vive en la capital, seguía las clases por vídeo sin problemas. Yo, en cambio, llegaba tarde a todas y perdía el hilo.","Sin embargo, no todo fue negativo: descubrí cursos gratuitos en línea y aprendí a organizarme sola. Ahora pienso que la escuela digital puede ayudar, siempre y cuando todos tengamos los mismos medios."],"source":"Témoignage imaginé pour l’exercice"},{"id":"medidas","type":"tableau","titre":"Tres respuestas al reto digital","colonnes":["Medida","En qué consiste"],"lignes":[["Plan Ceibal (Uruguay, 2007)","Un ordenador portátil para cada alumno de la escuela pública"],["Cursos MOOC en español","Cursos gratuitos de universidades de España y América Latina"],["Enseñanza a distancia de 2020","Clases en línea durante el cierre de los centros"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Dans le témoignage, touche les deux mots qui désignent le matériel et le réseau dont Valentina manque.","aide":"Un appareil pour trois frères et sœurs, et ce qui se coupe quand il pleut.","type":"zone","document":"valentina","multiple":true},{"enonce":"Range ces éléments du témoignage : avantage ou limite de l’école en ligne ?","aide":"Demande-toi si l’élément l’aide à apprendre ou la gêne.","type":"categories","categories":[{"id":"c0","texte":"Avantage"},{"id":"c1","texte":"Limite"}],"items":[{"id":"i0","texte":"Llegaba tarde a las clases y perdía el hilo"},{"id":"i1","texte":"Aprendió a organizarse sola"},{"id":"i2","texte":"Hay un solo móvil para tres hermanos"},{"id":"i3","texte":"Descubrió cursos gratuitos en línea"},{"id":"i4","texte":"La conexión se corta cuando llueve"}]},{"enonce":"Quelle mesure du tableau s’attaque directement au manque d’ordinateur dont souffre Valentina ?","aide":"Quel dispositif distribue du matériel aux élèves ?","type":"choix","options":[{"id":"a","texte":"L’enseignement à distance de 2020 pendant la fermeture des lycées"},{"id":"b","texte":"Les cours MOOC : des cours gratuits d’universités hispanophones"},{"id":"c","texte":"Le Plan Ceibal : un ordinateur portable pour chaque élève du public"},{"id":"d","texte":"Une aide pour vérifier les informations douteuses sur les réseaux"}],"multiple":false},{"enonce":"Complète la conclusion de Valentina.","aide":"Après « siempre y cuando », on emploie le subjonctif ; le verbe principal est au présent.","type":"trous","segments":["La escuela digital es una oportunidad siempre y cuando todos los alumnos ",0," acceso a internet."],"banque":["tendrán","tuvieran","tienen","tengan"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m37","m43"]},"explication":"Le **móvil** unique et la **conexión** instable montrent la *brecha digital* : Valentina n’a pas les mêmes moyens que Clara."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c1"}},"explication":"Les cours gratuits et l’autonomie sont des **avantages** ; la connexion qui coupe, le téléphone partagé et le retard pris sont des **limites**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le **Plan Ceibal** (Uruguay, 2007) donne un ordinateur à chaque élève du public : il répond au manque de matériel."},{"cle":{"type":"trous","trous":[["tengan"]]},"affichage":"tengan","explication":"« Siempre y cuando » exige le subjonctif présent : **tengan**."}]$ex$::jsonb),
  ('2696904f-f570-5986-8c33-4539028b36a8'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Une chanteuse qui revient pour une bière","competence":"analyser-document","situation":"Une marque de bière a choisi de faire « revivre » une chanteuse célèbre dans sa publicité. Observe la fiche d’analyse de l’annonce.","documents":[{"id":"anuncio","type":"tableau","titre":"Análisis del anuncio «Con mucho acento»","colonnes":["Elemento","En el anuncio"],"lignes":[["Marca","Cruzcampo"],["Año","2021"],["Personaje","Lola Flores, cantante fallecida, recreada con inteligencia artificial"],["Valor que se vende","El orgullo de los acentos andaluces"],["Emoción principal","La nostalgia"]],"enteteLignes":false,"source":"Fiche d’analyse écrite pour l’exercice, d’après la publicité Cruzcampo de 2021"}],"questions":[{"enonce":"Touche la case qui indique la valeur que la marque cherche à vendre, au-delà de la bière.","aide":"La marque ne vend pas seulement un produit : elle vend une fierté.","type":"zone","document":"anuncio","multiple":false},{"enonce":"Comment cette publicité cherche-t-elle à séduire son public ?","aide":"Regarde les lignes « Personaje » et « Emoción principal ».","type":"choix","options":[{"id":"a","texte":"En jouant sur la nostalgie et la fierté régionale grâce à une star disparue"},{"id":"b","texte":"En comparant les prix de plusieurs marques de bière sur un tableau"},{"id":"c","texte":"En interdisant l’accent andalou dans toutes les publicités du pays"},{"id":"d","texte":"En présentant un scientifique qui explique la recette de la bière"}],"multiple":false},{"enonce":"Associe chaque mot de la publicité à sa traduction.","aide":"« Público objetivo » n’est pas « le public objectif ».","type":"association","gauche":[{"id":"g0","texte":"el anuncio"},{"id":"g1","texte":"el eslogan"},{"id":"g2","texte":"el público objetivo"},{"id":"g3","texte":"seducir"}],"droite":[{"id":"d0","texte":"le slogan"},{"id":"d1","texte":"la publicité"},{"id":"d2","texte":"séduire"},{"id":"d3","texte":"la cible"}]},{"enonce":"Complète l’analyse avec le verbe du cours.","aide":"Le sujet est « el anuncio » (3e personne du singulier, présent).","type":"trous","segments":["El anuncio ",0," a la nostalgia de los espectadores."],"banque":["apelar","apelaba","apelan","apela"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c1"]},"explication":"La case **« El orgullo de los acentos andaluces »** donne la valeur vendue : la publicité associe la bière à une identité régionale."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’annonce fait appel à l’**émotion** (nostalgie) et à une **identité** (l’accent andalou) grâce à Lola Flores recréée."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g3":"d2","g2":"d3"}},"explication":"**Anuncio** = publicité ; **eslogan** = slogan ; **público objetivo** = cible ; **seducir** = séduire."},{"cle":{"type":"trous","trous":[["apela"]]},"affichage":"apela","explication":"On dit « El anuncio **apela** a… » pour montrer sur quoi une publicité joue."}]$ex$::jsonb),
  ('2696904f-f570-5986-8c33-4539028b36a8'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Ce qui se perd dans la traduction","competence":"manier-langue","situation":"Camille, une amie française de Nuria, utilise un traducteur automatique pour lui écrire. Le résultat est plein de surprises.","documents":[{"id":"sms2","type":"dialogue","modele":"sms","titre":"Mensajes entre amigas","participants":[{"nom":"Camille","emoji":"👩","cote":"gauche"},{"nom":"Nuria","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Camille","texte":"Hola Nuria. Ayer, en la cena con tus padres, estaba muy embarazada por mi acento."},{"qui":"Nuria","texte":"¿Cómo? Querrás decir que te daba vergüenza 😄"},{"qui":"Camille","texte":"El traductor automático me lo propuso. ¿Y en el museo? Pregunté por el éxito y nadie me entendía."},{"qui":"Nuria","texte":"Son dos falsos amigos: el primero significa «enceinte» y el segundo, «succès»."},{"qui":"Camille","texte":"¡Qué vergüenza! Desde hoy contrasto cada palabra en el diccionario."},{"qui":"Nuria","texte":"Bien hecho: la máquina traduce rápido, pero no entiende el humor ni la cultura."}],"source":"SMS écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux faux amis que Camille emploie à tort dans ses messages.","aide":"Ils ressemblent à des mots français mais n’ont pas le même sens.","type":"zone","document":"sms2","multiple":true},{"enonce":"Associe chaque mot à son sens réel en français.","aide":"Camille voulait dire « gênée » et « sortie ».","type":"association","gauche":[{"id":"g0","texte":"embarazada"},{"id":"g1","texte":"avergonzada"},{"id":"g2","texte":"éxito"},{"id":"g3","texte":"salida"}],"droite":[{"id":"d0","texte":"enceinte"},{"id":"d1","texte":"succès"},{"id":"d2","texte":"gênée, honteuse"},{"id":"d3","texte":"sortie"}]},{"enonce":"Selon Nuria, que comprend mal une traduction automatique ?","aide":"Relis sa dernière réplique.","type":"choix","options":[{"id":"a","texte":"Les noms propres des villes espagnoles"},{"id":"b","texte":"Les mots très courts comme les articles"},{"id":"c","texte":"Les chiffres et les dates de naissance"},{"id":"d","texte":"L’humour et les références culturelles"}],"multiple":false},{"enonce":"Aide Camille à poser la bonne question dans le musée.","aide":"Camille cherchait le contraire de « l’entrée ».","type":"trous","segments":["¿Dónde está la ",0," del museo?"],"banque":["entrada","éxito","vergüenza","salida"]}]}$ex$::jsonb,
