  ('2696904f-f570-5986-8c33-4539028b36a8'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Colomb, Allende, Calle 13 et une bière","competence":"analyser-document","situation":"Quatre textes, quatre formes de discours : compare leur destinataire et leur but, puis formule une critique en espagnol.","documents":[{"id":"formas","type":"tableau","titre":"Cuatro maneras de convencer","colonnes":["Texto","Forma","Destinatario","Objetivo"],"lignes":[["Último discurso de Allende (1973)","Discurso por radio","El pueblo chileno","Hablar para la historia"],["Anuncio de Cruzcampo (2021)","Publicidad","Los consumidores","Asociar la cerveza al orgullo andaluz"],["Carta de Colón (1493)","Carta","Los Reyes Católicos","Anunciar el descubrimiento y obtener más apoyo"],["«Latinoamérica» (2011)","Canción de rap","El público joven","Expresar la identidad de un continente"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche la case qui donne le destinataire du discours prononcé à la radio.","aide":"Repère la ligne du discours par radio, puis la colonne « Destinatario ».","type":"zone","document":"formas","multiple":false},{"enonce":"Remets ces quatre textes dans l’ordre chronologique, du plus ancien au plus récent.","aide":"Les années sont dans la première colonne.","type":"ordre","items":[{"id":"a","texte":"Último discurso de Allende"},{"id":"b","texte":"Anuncio de Cruzcampo"},{"id":"c","texte":"Carta de Colón"},{"id":"d","texte":"«Latinoamérica»"}]},{"enonce":"Quel point commun y a-t-il entre la lettre de Colomb et la publicité de Cruzcampo ?","aide":"Compare les colonnes « Destinatario » et « Objetivo » de ces deux lignes.","type":"choix","options":[{"id":"a","texte":"Les deux ont été écrites pour informer sans chercher à convaincre personne"},{"id":"b","texte":"Les deux sont des chansons qui expriment l’identité d’un continent entier"},{"id":"c","texte":"Les deux visent à convaincre un destinataire précis en appuyant sur ses attentes"},{"id":"d","texte":"Les deux s’adressent au même peuple et ont été écrites la même année"}],"multiple":false},{"enonce":"Complète la critique de la publicité Cruzcampo.","aide":"Après « cabe », on emploie l’infinitif.","type":"trous","segments":["Sin embargo, cabe ",0," el uso de la imagen de una persona fallecida."],"banque":["cuestionaba","cuestionar","cuestiona","cuestionado"]}]}$ex$::jsonb,
