  ('90bcf716-5469-5c24-8928-a7192ddd4a29'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Peñalta, le village qui se vide","competence":"analyser-texte","situation":"Un reportage imaginé raconte la vie d’un village de l’intérieur de l’Espagne. Lis-le, puis travaille sur sa construction.","documents":[{"id":"penalta","type":"texte","genre":"article","titre":"El pueblo que se vacía","blocs":["La plaza mayor de Peñalta, un pueblo imaginario del interior de Teruel, ya no se llena los domingos. Desde hace veinte años, los jóvenes se marchan a la ciudad en busca de trabajo y de estudios, y la escuela cerró.","Sin embargo, en 2019 la candidatura Teruel Existe entró en el Parlamento y llevó el problema de la España vaciada al debate nacional.","Hoy algunos vecinos vuelven gracias al teletrabajo. Reclaman mejores carreteras, médicos y conexión a internet. Es imprescindible que el Gobierno garantice estos servicios, dicen, para que el campo no muera."],"source":"Reportaje imaginado pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots qui expliquent pourquoi les jeunes quittent le village.","aide":"Que vont chercher les jeunes en ville ?","type":"zone","document":"penalta","multiple":true},{"enonce":"Que provoque l’entrée de Teruel Existe au Parlement, d’après le reportage ?","aide":"Relis le deuxième paragraphe : que « lleva » la candidatura au débat national ?","type":"choix","options":[{"id":"a","texte":"Le problème des régions qui se vident entre dans le débat national"},{"id":"b","texte":"La fermeture définitive de toutes les écoles rurales du pays"},{"id":"c","texte":"L’interdiction du télétravail dans les petites communes"},{"id":"d","texte":"Le retour immédiat de tous les jeunes dans leur village natal"}],"multiple":false},{"enonce":"Complète l’exigence des habitants.","aide":"Après « es imprescindible que », le subjonctif présent s’impose.","type":"trous","segments":["Es imprescindible que el Gobierno ",0," estos servicios."],"banque":["garantizara","garantice","garantizará","garantiza"]},{"enonce":"Remets les morceaux dans l’ordre pour former la formule qui concède puis réfute.","aide":"La concession vient d’abord, la réfutation ensuite.","type":"ordre","items":[{"id":"a","texte":"no es menos cierto que"},{"id":"b","texte":"Si bien es cierto que"},{"id":"c","texte":"sus vecinos siguen luchando."},{"id":"d","texte":"el pueblo se ha vaciado,"}]}]}$ex$::jsonb,
