   $ex${"titre":"Día de Muertos et autres rencontres","competence":"analyser-document","situation":"Un court reportage sur une fête mexicaine et un tableau sur trois figures du syncrétisme religieux.","documents":[{"id":"altar","type":"texte","genre":"article","titre":"Un altar en Oaxaca","blocs":["En Oaxaca, a principios de noviembre, la familia de Rosa prepara un altar: velas, flores de cempasúchil, pan de muerto y la foto de su abuela. Los pueblos prehispánicos ya honraban a sus antepasados con ofrendas de comida.","Hoy esta tradición coincide con la fiesta católica de Todos los Santos, y las dos se mezclan en el cementerio: misa por la mañana, música y comida por la tarde."],"source":"Reportage écrit pour l’exercice"},{"id":"sincretismo","type":"tableau","titre":"Tres lugares, una mezcla","colonnes":["Lugar","Tradición de origen","Figura católica"],"lignes":[["México (colina del Tepeyac)","Culto a la diosa Tonantzin","?"],["Cuba (santería)","Yemayá, divinidad yoruba","?"],["Potosí (Bolivia)","La Pachamama, la Tierra madre","?"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux adjectifs qui désignent les deux traditions qui se mêlent dans la fête.","aide":"Une tradition d’avant la conquête et une tradition chrétienne.","type":"zone","document":"altar","multiple":true},{"enonce":"Touche la case du tableau qui cite une divinité andine.","aide":"Cherche la Terre mère des Andes.","type":"zone","document":"sincretismo","multiple":false},{"enonce":"Complète les cases « ? » : associe chaque figure d’origine à la figure catholique qui lui répond.","aide":"Chaque divinité d’origine a un « double » catholique.","type":"association","gauche":[{"id":"g0","texte":"Tonantzin"},{"id":"g1","texte":"Yemayá"},{"id":"g2","texte":"Pachamama"},{"id":"g3","texte":"Changó"}],"droite":[{"id":"d0","texte":"sainte Barbe"},{"id":"d1","texte":"la Vierge de Guadalupe"},{"id":"d2","texte":"la Virgen del Cerro"},{"id":"d3","texte":"la Vierge de Regla"}]},{"enonce":"Complète la conclusion.","aide":"La phrase oppose « lejos de » à « ha enriquecido ».","type":"trous","segments":["Lejos de ",0," la cultura mexicana, el mestizaje la ha enriquecido."],"banque":["enriquecer","olvidar","empobrecer","separar"]}]}$ex$::jsonb,
