   $ex${"titre":"Huit siècles de rencontres","competence":"se-reperer-temps","situation":"Une frise rassemble des repères du métissage hispanique. Un texte d’élève nuance ensuite l’image d’un métissage « heureux ».","documents":[{"id":"frise10","type":"frise","titre":"Encuentros de culturas","debut":700,"fin":2020,"pas":100,"periodes":[{"id":"z1","debut":711,"fin":1492,"nom":"Al-Andalus","teinte":"ambre"},{"id":"z2","debut":1539,"fin":1616,"nom":"Garcilaso","teinte":"turquoise"}],"evenements":[{"id":"z3","date":1200,"nom":"Escuela de Toledo"},{"id":"z4","date":1492,"nom":"Gramática Nebrija"},{"id":"z5","date":1531,"nom":"Guadalupe"},{"id":"z6","date":1609,"nom":"Comentarios reales"},{"id":"z7","date":1925,"nom":"La raza cósmica"}],"source":"Frise écrite pour l’exercice"},{"id":"opinion","type":"texte","genre":"article","titre":"¿Una mezcla feliz?","blocs":["Se suele decir que el mestizaje es una mezcla feliz de culturas. No hay que olvidar que este mestizaje nació de la conquista. Sin embargo, lejos de empobrecer a los pueblos de América, creó culturas nuevas: la Virgen de Guadalupe, la santería o la cocina nikkei no existirían sin encuentros, a veces violentos, entre mundos distintos."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche la période de présence musulmane dans la péninsule ibérique.","aide":"Cherche la plus longue barre de la frise.","type":"zone","document":"frise10","multiple":false},{"enonce":"Combien d’années séparent 711 de 1492, dates qui bornent al-Andalus ?","aide":"Soustrais 711 de 1492.","type":"nombre","unite":"ans"},{"enonce":"Touche le repère où des savants chrétiens, juifs et musulmans traduisent ensemble, puis la période de vie du premier grand écrivain métis.","aide":"Le premier est au XIIe-XIIIe siècle ; le second est le fils d’un conquistador et d’une princesse inca.","type":"zone","document":"frise10","multiple":true},{"enonce":"Quelle phrase nuance une vision idéale du métissage ?","aide":"Cherche la formule qui rappelle un fait historique dérangeant.","type":"choix","options":[{"id":"a","texte":"Las culturas nuevas han desaparecido por culpa del mestizaje."},{"id":"b","texte":"La santería y la cocina nikkei no tienen nada que ver con él."},{"id":"c","texte":"No hay que olvidar que este mestizaje nació de la conquista."},{"id":"d","texte":"El mestizaje es siempre una mezcla feliz y pacífica de culturas."}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Le sujet est pluriel : « tradiciones ».","type":"trous","segments":["Las tradiciones prehispánicas y católicas ",0," en el Día de Muertos."],"banque":["se funden","se funde","confluye","confluyen"]}]}$ex$::jsonb,
