   $ex${"titre":"Quelle concordance ?","competence":"manier-langue","situation":"Un correcteur relit six phrases d’élèves. Trois enfreignent la concordance des temps du subjonctif.","documents":[{"id":"frases11","type":"tableau","titre":"Seis frases de un examen","colonnes":["N.º","Frase"],"lignes":[["1","Quería que vengas conmigo."],["2","Le he pedido que venga."],["3","Me gustaría que vinieras."],["4","Te pedí que me ayudes."],["5","Espero que tengas suerte."],["6","Buscaba a alguien que hable ruso."]],"enteteLignes":false,"source":"Phrases écrites pour l’exercice"}],"questions":[{"enonce":"Touche les trois phrases où le subjonctif ne s’accorde pas au temps du verbe principal.","aide":"Cherche un verbe principal à l’imparfait ou au passé simple suivi d’un subjonctif présent.","type":"zone","document":"frases11","multiple":true},{"enonce":"Quelle correction faut-il apporter à la phrase 1 ?","aide":"Verbe principal à l’imparfait : la subordonnée se met à l’imparfait du subjonctif.","type":"choix","options":[{"id":"a","texte":"Mettre l’indicatif : « Quería que vienes conmigo »"},{"id":"b","texte":"Mettre l’imparfait du subjonctif : « Quería que vinieras conmigo »"},{"id":"c","texte":"Mettre le futur : « Quería que vendrás conmigo »"},{"id":"d","texte":"Mettre le conditionnel : « Quería que vendrías conmigo »"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"« Quería » est à l’imparfait.","type":"trous","segments":["Mi madre quería que yo ",0," medicina."],"banque":["estudiara","estudie","estudio","estudiaba"]},{"enonce":"Remets les morceaux dans l’ordre pour former la phrase.","aide":"Le passé composé est un temps du présent : subjonctif présent.","type":"ordre","items":[{"id":"a","texte":"Le he pedido"},{"id":"b","texte":"venga"},{"id":"c","texte":"pronto."},{"id":"d","texte":"que"}]}]}$ex$::jsonb,
