   $ex${"titre":"La lettre de la grand-mère","competence":"analyser-texte","situation":"Une grand-mère écrit à son petit-fils. Sa lettre contient plusieurs subordonnées qui illustrent tous les cas de concordance.","documents":[{"id":"abuela","type":"texte","genre":"lettre","titre":"Carta de la abuela Rosa","blocs":["Querido Tomás:","Me alegro mucho de que hayas aprobado el examen. Ayer, por teléfono, hablabas como si ya hubieras suspendido, y me preocupé.","Cuando eras pequeño, quería que aprendieras a tocar la guitarra, pero no encontré a nadie que te enseñara. Hoy busco a alguien que me enseñe a usar el móvil. Te llamaré cuando llegues a casa.","Un beso, la abuela Rosa."],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche l’auxiliaire qui montre que l’action d’avoir réussi l’examen est antérieure au moment où parle la grand-mère.","aide":"C’est la première forme du verbe « haber » du texte.","type":"zone","document":"abuela","multiple":false},{"enonce":"Complète pour dire que l’action était terminée avant.","aide":"Verbe principal au passé + action antérieure : plus-que-parfait du subjonctif.","type":"trous","segments":["Me alegré de que ",0," venido."],"banque":["habrías","hubieras","habías","hayas"]},{"enonce":"Pourquoi la grand-mère écrit-elle « quería que aprendieras » ?","aide":"Regarde le temps du verbe principal.","type":"choix","options":[{"id":"a","texte":"Parce que Tomás est un enfant dans le souvenir"},{"id":"b","texte":"Le verbe principal « quería » est à l’imparfait"},{"id":"c","texte":"Parce que le subjonctif présent n’existe pas ici"},{"id":"d","texte":"Le verbe « aprender » exige toujours l’imparfait"}],"multiple":false},{"enonce":"Complète avec « como si ».","aide":"Après « como si » : imparfait ou plus-que-parfait du subjonctif.","type":"trous","segments":["Habla como si ",0," vivido siempre aquí."],"banque":["ha","hubiera","haya","había"]},{"enonce":"Comment mettre « Busco a alguien que me enseñe » au passé ?","aide":"Relative + verbe principal au passé : imparfait du subjonctif.","type":"choix","options":[{"id":"a","texte":"Buscaba a alguien que me enseñe"},{"id":"b","texte":"Buscaba a alguien que me enseñara"},{"id":"c","texte":"Buscaba a alguien que me enseñaría"},{"id":"d","texte":"Buscaba a alguien que me enseña"}],"multiple":false}]}$ex$::jsonb,
