  ('01489fad-4780-5d1f-9498-b695c4e2adee'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le village sous l’eau et les œuvres contre l’oubli","competence":"analyser-document","situation":"Un court article imaginé sur un village englouti et un tableau d’œuvres qui luttent contre l’oubli : croise les deux.","documents":[{"id":"valdeagua","type":"texte","genre":"article","titre":"El pueblo bajo el agua","blocs":["Cuando se llenó el embalse, el pueblo de Valdeagua desapareció bajo el agua. Los vecinos perdieron su tierra y, con ella, su memoria.","Cada verano, cuando baja el nivel del agua, reaparece el campanario. Los descendientes vuelven a verlo: para ellos, es mucho más que una ruina. Cabe plantearse si el progreso justifica este olvido."],"source":"Article imaginé pour l’exercice"},{"id":"obras12","type":"tableau","titre":"Obras contra el olvido","colonnes":["Obra","Tipo","Cómo trabaja la memoria"],"lignes":[["Madres paralelas (2021)","Película","Termina con la apertura de una fosa común"],["Soldados de Salamina (2001)","Novela","Relato real sobre un episodio de la guerra civil"],["Fragmentos (2018)","Instalación artística","Un suelo hecho con armas fundidas de las FARC"],["El laberinto del fauno (2006)","Película","Cuento fantástico en la España de 1944"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots qui désignent ce que les habitants ont perdu.","aide":"Ils sont dans la deuxième phrase, l’un matériel, l’autre immatériel.","type":"zone","document":"valdeagua","multiple":true},{"enonce":"Que signifie « Cabe plantearse si el progreso justifica este olvido » ?","aide":"« Cabe + infinitif » ouvre une réflexion, une question à se poser.","type":"choix","options":[{"id":"a","texte":"Il faut se demander si le progrès justifie cet oubli"},{"id":"b","texte":"Il est certain que le progrès justifie cet oubli"},{"id":"c","texte":"Il suffit de se souvenir pour que le progrès continue"},{"id":"d","texte":"Il est interdit de se demander si le progrès est utile"}],"multiple":false},{"enonce":"Touche la case qui décrit une œuvre faite avec des armes fondues.","aide":"Cherche « armas fundidas » dans la dernière colonne.","type":"zone","document":"obras12","multiple":false},{"enonce":"Range ces œuvres de la plus ancienne à la plus récente.","aide":"Les années sont entre parenthèses.","type":"ordre","items":[{"id":"a","texte":"Madres paralelas"},{"id":"b","texte":"Soldados de Salamina"},{"id":"c","texte":"El laberinto del fauno"},{"id":"d","texte":"Fragmentos"}]},{"enonce":"Complète la conclusion nuancée.","aide":"Expression figée qui signifie « en fin de compte ».","type":"trous","segments":["A fin de ",0,", no se trata de reabrir heridas, sino de cerrarlas con verdad."],"banque":["cuento","contar","cuentas","cuenta"]}]}$ex$::jsonb,
