  ('ad15b82e-d413-5ee2-9631-49ba82ebfcc7'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La chanson de l’usine","competence":"analyser-texte","situation":"Tu prépares un commentaire sur l’art engagé. Voici les quatre vers d’une chanson de protestation : cherche qui elle accuse et comment elle le fait.","documents":[{"id":"chanson","type":"texte","genre":"poeme","titre":"The Factory Whistle","blocs":["The whistle blows at dawn, the whistle blows at night,","The owner counts his coins, we work by candlelight.","They call it progress, but we call it a chain,","They call it progress, and we’re the ones in pain."],"source":"Chanson écrite pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui désigne la personne que la chanson accuse.","aide":"C’est celui qui compte son argent pendant que les autres travaillent.","type":"zone","document":"chanson","multiple":false},{"enonce":"Touche le mot que les travailleurs emploient à la place de « progress ».","aide":"Cherche le mot qui montre qu’ils se sentent prisonniers.","type":"zone","document":"chanson","multiple":false},{"enonce":"Que pense le chanteur du mot « progress » ?","aide":"Lis le vers 3 : « They call it progress, but we call it… ».","type":"choix","options":[{"id":"a","texte":"Il pense que le progrès est inévitable et qu’il faut donc l’accepter en silence"},{"id":"b","texte":"Il l’admire car les usines créent des richesses pour tout le monde à la fois"},{"id":"c","texte":"Il le reprend pour montrer qu’il enrichit le patron et enchaîne les ouvriers"},{"id":"d","texte":"Il le juge trop compliqué pour que les ouvriers puissent le comprendre un jour"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11"]},"explication":"C’est **owner** : le propriétaire de l’usine, cible de la chanson (étape 1 de la méthode : la cible)."},{"cle":{"type":"zone","ids":["m28"]},"explication":"Les ouvriers disent **chain** (une chaîne) : pour eux, ce que les patrons appellent le progrès est une entrave."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le chanteur répète le mot des patrons pour le **retourner** : le progrès dont ils parlent ne profite qu’à eux."}]$ex$::jsonb),
