   $ex${"titre":"Swift expliqué par deux amis","competence":"comprendre-langue","situation":"Maya et Jack discutent de *A Modest Proposal*. Suis leur échange, puis utilise le petit tableau pour reconnaître trois autres œuvres engagées.","documents":[{"id":"swift","type":"dialogue","modele":"sms","titre":"Un échange sur Swift","participants":[{"nom":"Maya","emoji":"👩","cote":"gauche"},{"nom":"Jack","emoji":"🧑","cote":"droite"}],"repliques":[{"qui":"Maya","texte":"I’ve just read A Modest Proposal. Swift suggests that poor families should sell their babies as food!"},{"qui":"Jack","texte":"Seriously? Does he really want that?"},{"qui":"Maya","texte":"No! He is being ironic. He says the opposite of what he thinks."},{"qui":"Jack","texte":"So who is he attacking?"},{"qui":"Maya","texte":"The rich landlords who ignore the poor. The narrator stays calm, and that’s what makes it horrifying."}],"source":"Dialogue écrit pour l’exercice"},{"id":"indices","type":"tableau","titre":"Trois œuvres, trois indices","colonnes":["Clue","Year"],"lignes":[["A farm where the pigs become the new masters",1945],["Chicago slaughterhouses seen through an immigrant family",1906],["An enslaved man’s suffering shown from the inside",1852]],"enteteLignes":false,"source":"Indices rédigés pour l’exercice"}],"questions":[{"enonce":"Touche le mot anglais qui nomme le procédé utilisé par Swift.","aide":"Il consiste à dire le contraire de ce qu’on pense.","type":"zone","document":"swift","multiple":false},{"enonce":"Touche l’adjectif qui décrit le ton du narrateur.","aide":"Le narrateur ne s’énerve jamais.","type":"zone","document":"swift","multiple":false},{"enonce":"Qui Swift attaque-t-il vraiment dans le texte évoqué ?","aide":"Relis la dernière réplique de Maya.","type":"choix","options":[{"id":"a","texte":"Les familles irlandaises qui ne savent pas gérer leur budget"},{"id":"b","texte":"Les lecteurs français de son époque qui ignorent l’Irlande"},{"id":"c","texte":"Les riches propriétaires qui se désintéressent du sort des pauvres"},{"id":"d","texte":"Les enfants pauvres que personne n’envoie à l’école"}],"multiple":false},{"enonce":"Associe chaque indice du document 2 à l’œuvre correspondante.","aide":"Les cochons, Chicago, l’esclavage : trois univers très différents.","type":"association","gauche":[{"id":"g0","texte":"A farm where the pigs become the new masters"},{"id":"g1","texte":"Chicago slaughterhouses seen through an immigrant family"},{"id":"g2","texte":"An enslaved man’s suffering shown from the inside"}],"droite":[{"id":"d0","texte":"Uncle Tom’s Cabin"},{"id":"d1","texte":"The Jungle"},{"id":"d2","texte":"Animal Farm"}]},{"enonce":"Combien d’années séparent le roman sur les abattoirs de celui sur les cochons ?","aide":"Soustrais les deux dates du tableau.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
