  ('ad15b82e-d413-5ee2-9631-49ba82ebfcc7'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le mur de Mill Street","competence":"analyser-document","situation":"Un article et un panneau officiel racontent le même événement. Croise-les pour mesurer l’effet d’une œuvre qui dénonce.","documents":[{"id":"article","type":"texte","genre":"article","titre":"A Wall That Would Not Stay Silent","blocs":["Last Tuesday, a stencilled mural appeared on the wall of the closed Mill Street factory. It shows a smiling boss with enormous hands giving a single coin to a long line of workers, beneath the words “SHARE THE PROFIT”.","The mural is a caricature: the boss’s hands are huge, his head is tiny and his smile never changes. The workers, by contrast, are drawn with great care.","The factory owner, who has just closed two workshops, called it “vandalism”. Residents, however, have started to leave flowers at the foot of the wall.","“Art should not flatter power,” said a local teacher. “It should ask questions.”"],"source":"Article imaginé pour l’exercice"},{"id":"panneau","type":"fiche","modele":"panneau","entete":"NOTICE — Mill Street Council","sousTitre":"Public walls","emoji":"⚠️","lignes":[{"texte":"Unauthorised paintings on public walls","id":"z1"},{"texte":"will be removed on Friday at 8 a.m.","id":"z2"},{"texte":"Offenders may be fined up to £500","id":"z3"}],"pied":"By order of the Council"}],"questions":[{"enonce":"Touche le mot par lequel le propriétaire qualifie la fresque.","aide":"Il est entre guillemets, dans le troisième paragraphe.","type":"zone","document":"article","multiple":false},{"enonce":"Quelle est la cible de la fresque ?","aide":"Regarde ce que fait le personnage dessiné avec sa pièce.","type":"choix","options":[{"id":"a","texte":"Les habitants qui déposent des fleurs au pied du mur de l’usine"},{"id":"b","texte":"Les ouvriers qui refusent de changer d’atelier quand on le leur demande"},{"id":"c","texte":"La mairie qui veut effacer toutes les peintures des murs publics"},{"id":"d","texte":"Le patron qui ferme des ateliers et garde les profits pour lui"}],"multiple":false},{"enonce":"Touche le mot qui nomme le procédé du dessin : des traits exagérés pour faire rire et faire honte.","aide":"Ce mot ressemble beaucoup au français « caricature ».","type":"zone","document":"article","multiple":false},{"enonce":"Sur le panneau, touche la ligne qui annonce ce qui arrivera à la fresque.","aide":"Cherche le verbe « removed ».","type":"zone","document":"panneau","multiple":false},{"enonce":"Que montre l’opposition entre le panneau de la mairie et les fleurs des habitants ?","aide":"Méthode, étape 4 : l’effet. Qu’a déclenché l’œuvre ?","type":"choix","options":[{"id":"a","texte":"Que l’œuvre a un effet réel : elle oppose l’autorité aux habitants"},{"id":"b","texte":"Que les habitants n’ont pas compris l’ironie de la fresque peinte"},{"id":"c","texte":"Que la fresque est sans intérêt puisqu’elle sera bientôt effacée"},{"id":"d","texte":"Que la mairie soutient discrètement l’artiste contre le propriétaire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m78"]},"explication":"Le propriétaire parle de **vandalism** (dégradation) : il refuse de voir une œuvre dans ce dessin."},{"cle":{"type":"choix","ids":["d"]},"explication":"La fresque vise le **patron** : il garde presque tout et ne donne qu’une pièce, d’où le slogan « SHARE THE PROFIT »."},{"cle":{"type":"zone","ids":["m43"]},"explication":"C’est une **caricature** : mains énormes, tête minuscule, sourire figé, l’exagération rend le patron ridicule."},{"cle":{"type":"zone","ids":["z2"]},"explication":"La ligne « will be removed on Friday at 8 a.m. » annonce que la fresque sera **effacée**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Les fleurs et le panneau prouvent que la fresque a provoqué un **conflit public** : c’est l’effet d’une œuvre qui dénonce."}]$ex$::jsonb),
