  ('0d8ff6f5-24d4-508e-ad5e-f6d97cc33e79'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le censeur de 1936","competence":"analyser-texte","situation":"Dans les années 1930, un studio hollywoodien reçoit cette lettre. Lis-la comme un cinéaste : que doit-on changer, et comment contourner l’interdit ?","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"A letter from the Production Code Office","blocs":["Dear Mr Harlow,","We have read your script, *The Last Train*. Three changes are required:","1. The gangster must not escape without punishment.","2. The kiss on the platform must be shorter.","3. The bedroom scene must be replaced by something more suitable.","With kind regards, The Production Code Office, 1936"],"source":"Lettre imaginée pour l’exercice, dans l’esprit du Code Hays"}],"questions":[{"enonce":"Touche le mot qui exprime la règle morale : le crime ne doit pas rester impuni.","aide":"Cherche ce que doit subir le gangster.","type":"zone","document":"lettre","multiple":false},{"enonce":"Combien de modifications le censeur exige-t-il ?","aide":"Les demandes sont numérotées.","type":"nombre"},{"enonce":"Associe chaque demande du censeur à sa traduction.","aide":"Traduis mot à mot : escape, kiss, bedroom.","type":"association","gauche":[{"id":"g0","texte":"The gangster must not escape without punishment"},{"id":"g1","texte":"The kiss on the platform must be shorter"},{"id":"g2","texte":"The bedroom scene must be replaced"}],"droite":[{"id":"d0","texte":"La scène de la chambre doit disparaître"},{"id":"d1","texte":"Le criminel doit être puni"},{"id":"d2","texte":"Le baiser doit être raccourci"}]},{"enonce":"Comment un cinéaste peut-il montrer la scène de chambre sans enfreindre le Code ?","aide":"Le cours dit que les cinéastes apprennent à « suggérer ».","type":"choix","options":[{"id":"a","texte":"En la remplaçant par un long discours du gangster face à la caméra"},{"id":"b","texte":"En la suggérant, par exemple avec un fondu enchaîné sur la scène suivante"},{"id":"c","texte":"En la montrant en entier mais avec un narrateur qui condamne les personnages"},{"id":"d","texte":"En la tournant en couleurs pour qu’elle paraisse plus artistique aux censeurs"}],"multiple":false}]}$ex$::jsonb,
