  ('0d8ff6f5-24d4-508e-ad5e-f6d97cc33e79'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une soupe, un urinoir, un débat","competence":"argumenter","situation":"Deux amis se disputent sur le pop art. Lis leur échange, puis compare leurs arguments au tableau du débat.","documents":[{"id":"debat","type":"dialogue","modele":"sms","titre":"Nora et Sam","participants":[{"nom":"Nora","emoji":"👩","cote":"gauche"},{"nom":"Sam","emoji":"🧑","cote":"droite"}],"repliques":[{"qui":"Nora","texte":"A soup can on a wall? That’s not art, it’s shopping!"},{"qui":"Sam","texte":"Warhol, 1962. He shows what consumer society puts in every kitchen, and it makes you look at it."},{"qui":"Nora","texte":"But anyone could have painted it."},{"qui":"Sam","texte":"Then why did nobody? Duchamp put a urinal in a gallery in 1917 and asked the same question: is it art because the artist says so?"},{"qui":"Nora","texte":"Well, some things should be banned if they shock children."},{"qui":"Sam","texte":"Every censor ends up looking foolish tomorrow. Ulysses was banned, and now it’s on every reading list."}],"source":"Dialogue écrit pour l’exercice"},{"id":"args","type":"tableau","titre":"Arguments in the debate","colonnes":["To limit","To protect"],"lignes":[["Protect young people","Freedom of speech (First Amendment)"],["Respect beliefs","Art may shock in order to make us think"],["Public order","Yesterday’s censor looks ridiculous today"]],"enteteLignes":false,"source":"D’après le cours"}],"questions":[{"enonce":"Touche le mot qui montre que, pour Sam, le pop art regarde la société de consommation.","aide":"C’est l’adjectif qui qualifie « society ».","type":"zone","document":"debat","multiple":false},{"enonce":"Dans le tableau, touche la case qui correspond à l’argument de Sam dans sa dernière réplique.","aide":"Sam parle de la censure d’*Ulysses*, ridicule avec le recul.","type":"zone","document":"args","multiple":false},{"enonce":"Quel rapport y a-t-il entre la question de Duchamp (1917) et celle de Warhol (1962) ?","aide":"Relis la réplique de Sam sur l’urinoir.","type":"choix","options":[{"id":"a","texte":"Toutes deux dénoncent la guerre par l’ironie d’un objet banal du quotidien"},{"id":"b","texte":"Toutes deux ont été interdites par le Code Hays à Hollywood dans les années 1930"},{"id":"c","texte":"Toutes deux sont des chansons engagées contre la censure d’État en Amérique"},{"id":"d","texte":"Toutes deux demandent si un objet du quotidien devient art parce que l’artiste le décide"}],"multiple":false},{"enonce":"Range ces phrases selon le camp dont elles relèvent, d’après le document 2.","aide":"Une colonne du tableau défend la limite, l’autre la liberté.","type":"categories","categories":[{"id":"c0","texte":"Pour limiter"},{"id":"c1","texte":"Pour protéger"}],"items":[{"id":"i0","texte":"Every censor looks foolish with hindsight"},{"id":"i1","texte":"Some things should be banned if they shock young people"},{"id":"i2","texte":"Public order must come first"},{"id":"i3","texte":"Art may shock in order to make us think"}]},{"enonce":"Quelle conclusion nuancée est la plus juste ?","aide":"Méthode, étape 4 : conclure en nuançant.","type":"choix","options":[{"id":"a","texte":"Ce qui choque change avec les époques : il faut peser l’ordre public et la liberté d’expression"},{"id":"b","texte":"Il ne faut jamais limiter une œuvre, quelles que soient ses conséquences pour autrui"},{"id":"c","texte":"Il faut interdire toute œuvre qui choque, car l’ordre public prime sur tout le reste du débat"},{"id":"d","texte":"Le pop art n’a jamais fait débat, car il reprend seulement des objets très familiers"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16"]},"explication":"Le mot **consumer** (de consommation) résume ce que Warhol montre : les objets du quotidien."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Sam reprend « **Yesterday’s censor looks ridiculous today** » (colonne « To protect »)."},{"cle":{"type":"choix","ids":["d"]},"explication":"Pour Duchamp (*Fountain*) comme pour Warhol (*Campbell’s Soup Cans*), la question est : **qu’est-ce qui fait qu’un objet est de l’art ?**"},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"« Protéger la jeunesse » et « l’ordre public » sont des arguments **pour limiter** ; la liberté d’expression et le recul du temps sont des arguments **pour protéger** l’art."},{"cle":{"type":"choix","ids":["a"]},"explication":"On conclut en **nuançant** : les critères changent, et le débat oppose deux valeurs qu’il faut peser."}]$ex$::jsonb),
  ('4536204e-6ca9-5503-a353-90734005fe75'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Une infirmière prend la parole","competence":"analyser-texte","situation":"Une infirmière prononce un discours sur l’hôpital. Retrouve dans ses trois phrases les trois leviers d’Aristote.","documents":[{"id":"discours","type":"texte","genre":"source","titre":"Hospital speech","blocs":["1. As a nurse for twenty years, I know what a hospital needs.","2. Last winter, a frightened little boy waited six hours in a corridor, holding my hand.","3. The figures are clear: waiting times have risen by thirty percent in five years."],"source":"Discours imaginé pour l’exercice"}],"questions":[{"enonce":"Associe chaque phrase du discours au levier qu’elle mobilise.","aide":"Crédibilité, émotion, logique : à toi de les reconnaître.","type":"association","gauche":[{"id":"g0","texte":"As a nurse for twenty years…"},{"id":"g1","texte":"A frightened little boy waited six hours…"},{"id":"g2","texte":"Waiting times have risen by thirty percent"}],"droite":[{"id":"d0","texte":"Pathos"},{"id":"d1","texte":"Logos"},{"id":"d2","texte":"Ethos"}]},{"enonce":"Touche le mot qui établit la crédibilité de l’oratrice.","aide":"Quel métier lui donne le droit de parler ?","type":"zone","document":"discours","multiple":false},{"enonce":"Touche le mot qui cherche à émouvoir le public.","aide":"Cherche un adjectif qui exprime la peur.","type":"zone","document":"discours","multiple":false},{"enonce":"Touche le mot qui renvoie à un raisonnement chiffré.","aide":"Il est attaché à un nombre.","type":"zone","document":"discours","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"La première phrase donne de la **crédibilité** (ethos), la deuxième touche les **émotions** (pathos), la troisième s’appuie sur des **faits chiffrés** (logos)."},{"cle":{"type":"zone","ids":["m3"]},"explication":"Le mot **nurse** montre qu’elle parle en connaissance de cause : c’est l’ethos."},{"cle":{"type":"zone","ids":["m17"]},"explication":"Le mot **frightened** (effrayé) vise l’émotion du public : c’est le pathos."},{"cle":{"type":"zone","ids":["m40"]},"explication":"Le mot **percent** (pour cent) appartient au registre des chiffres : c’est le logos."}]$ex$::jsonb),
  ('4536204e-6ca9-5503-a353-90734005fe75'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Clean Water Now","competence":"analyser-document","situation":"Un discours célèbre et un discours d’élève : repère les figures qui les rendent mémorables.","documents":[{"id":"lincoln","type":"texte","genre":"source","titre":"Gettysburg Address (1863), fin du discours","blocs":["…that government of the people, by the people, for the people, shall not perish from the earth."],"source":"Abraham Lincoln, *Gettysburg Address* (1863), dernière phrase"},{"id":"eau","type":"texte","genre":"source","titre":"Un discours d’élève","blocs":["We need clean water. We need it in our schools. We need it in our villages. We need it now.","Water gives life, and life needs water.","Is it too much to ask for a right that every child deserves?"],"source":"Discours imaginé pour l’exercice"}],"questions":[{"enonce":"Touche les trois petits mots qui rythment la série de trois dans la phrase de Lincoln.","aide":"Ce sont trois prépositions suivies de « the people ».","type":"zone","document":"lincoln","multiple":true},{"enonce":"Touche les quatre mots répétés au début des phrases du premier paragraphe.","aide":"Ils ouvrent chaque phrase.","type":"zone","document":"eau","multiple":true},{"enonce":"Range chaque phrase selon la figure qu’elle contient.","aide":"Une série de trois, une répétition en tête de phrase, une structure croisée A-B / B-A, une question sans réponse attendue.","type":"categories","categories":[{"id":"c0","texte":"Tricolon"},{"id":"c1","texte":"Anaphore"},{"id":"c2","texte":"Chiasme"},{"id":"c3","texte":"Question rhétorique"}],"items":[{"id":"i0","texte":"of the people, by the people, for the people"},{"id":"i1","texte":"Water gives life, and life needs water."},{"id":"i2","texte":"Is it too much to ask for a right that every child deserves?"},{"id":"i3","texte":"We need it in our schools. We need it in our villages."}]},{"enonce":"Quel est l’effet de l’anaphore « We need… » ?","aide":"Que produit une répétition au début de chaque phrase ?","type":"choix","options":[{"id":"a","texte":"Elle retourne le sens d’une phrase pour se moquer de l’adversaire en public"},{"id":"b","texte":"Elle martèle l’urgence et donne au discours un rythme qui s’imprime dans l’esprit"},{"id":"c","texte":"Elle cache la demande principale pour ménager le public de l’assemblée"},{"id":"d","texte":"Elle ajoute des chiffres qui prouvent l’ampleur du problème avec précision"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m5","m8"]},"explication":"Les mots **of, by, for** construisent le tricolon : trois groupes qui se suivent et scandent la phrase."},{"cle":{"type":"zone","ids":["m0","m4","m10","m16"]},"explication":"« **We** need… » est répété quatre fois : c’est une anaphore."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c3","i3":"c1"}},"explication":"**Tricolon** : série de trois ; **anaphore** : répétition de « We need » ; **chiasme** : life / water / water / life ; **question rhétorique** : on n’attend pas de réponse."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’anaphore **martèle** la demande : le public retient le rythme et sent l’urgence."}]$ex$::jsonb),
  ('4536204e-6ca9-5503-a353-90734005fe75'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Douter ou retourner la foule","competence":"analyser-texte","situation":"Deux façons de persuader : poser des questions à douze jurés, ou faire dire à un mot son contraire. Compare-les.","documents":[{"id":"jury","type":"texte","genre":"theatre","titre":"Jury room","blocs":[{"didascalie":"A small, hot room. Twelve chairs. One juror has not raised his hand."},{"personnage":"Juror 1","replique":"Eleven of us say guilty. Why are you waiting?"},{"personnage":"Juror 2","replique":"I don’t say he’s innocent. I say I have a doubt."},{"personnage":"Juror 1","replique":"A doubt? The witness saw everything!"},{"personnage":"Juror 2","replique":"From forty metres, at night? Let us ask ourselves whether she could."}],"source":"Scène écrite pour l’exercice, dans l’esprit de *12 Angry Men*"},{"id":"antoine","type":"texte","genre":"poeme","titre":"Julius Caesar, Acte III, scène 2 (Marc Antoine)","blocs":["But Brutus says he was ambitious;","And Brutus is an honourable man."],"source":"William Shakespeare, *Julius Caesar* (vers 1599)"}],"questions":[{"enonce":"Touche le mot qui résume la position du juré qui hésite.","aide":"Il ne dit pas « innocent », il dit autre chose.","type":"zone","document":"jury","multiple":false},{"enonce":"Sur quoi le juré fonde-t-il son doute ?","aide":"Relis la dernière réplique : « From forty metres, at night? »","type":"choix","options":[{"id":"a","texte":"Sur l’amitié entre le témoin et l’accusé, révélée par un avocat adverse"},{"id":"b","texte":"Sur les conditions dans lesquelles le témoin a vu la scène : la nuit et de loin"},{"id":"c","texte":"Sur l’absence de l’accusé à l’audience, qui rend le procès irrégulier"},{"id":"d","texte":"Sur l’âge du témoin, jugé trop élevé pour que son avis soit pris au sérieux"}],"multiple":false},{"enonce":"Touche l’adjectif qui, dans la bouche d’Antoine, finit par signifier son contraire.","aide":"Il qualifie Brutus et il est répété dans tout le discours.","type":"zone","document":"antoine","multiple":false},{"enonce":"En quoi les deux manières de persuader diffèrent-elles ?","aide":"L’un parle de preuves, l’autre joue avec le sens d’un mot.","type":"choix","options":[{"id":"a","texte":"Les deux orateurs mobilisent surtout l’émotion et des souvenirs personnels"},{"id":"b","texte":"Le juré utilise l’ironie, Antoine s’appuie sur des chiffres très précis"},{"id":"c","texte":"Le juré convainc en questionnant des faits, Antoine en retournant un mot par l’ironie"},{"id":"d","texte":"Le juré s’adresse à une foule entière, Antoine à douze hommes dans une salle"}],"multiple":false},{"enonce":"Associe chaque moyen de persuasion à son exemple dans les documents.","aide":"Un exemple vient de la pièce de Shakespeare, deux de la scène du jury.","type":"association","gauche":[{"id":"g0","texte":"Le logos (les faits)"},{"id":"g1","texte":"L’ironie"},{"id":"g2","texte":"Le doute méthodique"}],"droite":[{"id":"d0","texte":"« Brutus is an honourable man »"},{"id":"d1","texte":"« From forty metres, at night? »"},{"id":"d2","texte":"« I don’t say he’s innocent. I say I have a doubt. »"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m32"]},"explication":"Le juré dit qu’il a un **doubt** : il ne prétend pas savoir, il refuse de condamner sans certitude."},{"cle":{"type":"choix","ids":["b"]},"explication":"Son doute vient des **conditions d’observation** (quarante mètres, la nuit) : il interroge les faits."},{"cle":{"type":"zone","ids":["m10"]},"explication":"Antoine répète **honourable** jusqu’à ce qu’il sonne comme une accusation : c’est de l’ironie."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le juré s’appuie sur le **logos** (les faits) ; Antoine sur l’**ironie** d’un mot répété."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Le doute sur le témoin relève des **faits** ; la formule d’Antoine de l’**ironie** ; la réplique du juré du **doute méthodique**."}]$ex$::jsonb),
  ('1c30cae9-94e2-54bc-b83f-fb92f04ce3ca'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La fiche de Gilead","competence":"analyser-document","situation":"Tu prépares ta fiche sur *The Handmaid’s Tale*. Voici la carte d’identité du roman : lis-la avant de répondre.","documents":[{"id":"fiche","type":"fiche","modele":"affiche","entete":"BOOK FILE","sousTitre":"The Handmaid’s Tale","emoji":"📕","lignes":[{"texte":"Author","valeur":"Margaret Atwood"},{"texte":"First published","valeur":"1985"},{"texte":"Regime","valeur":"The Republic of Gilead","id":"z1"},{"texte":"Narrator","valeur":"Offred"},{"texte":"The Handmaids wear","valeur":"red dresses","id":"z2"},{"texte":"Last chapter","valeur":"Historical Notes, a symposium in 2195","id":"z3"}],"pied":"A dystopia","source":"Fiche rédigée pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui donne le nom du régime qui a remplacé les États-Unis.","aide":"Cherche le mot « Regime ».","type":"zone","document":"fiche","multiple":false},{"enonce":"Touche la ligne qui dit ce que portent les servantes.","aide":"Une couleur et un vêtement.","type":"zone","document":"fiche","multiple":false},{"enonce":"Combien d’années séparent la parution du roman du colloque évoqué dans le dernier chapitre ?","aide":"Soustrais la date de parution à la date du colloque.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Le régime s’appelle **la République de Gilead**."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Les servantes portent des **robes rouges** (*red dresses*), devenues un symbole de manifestation."},{"cle":{"type":"nombre","valeur":210,"tolerance":0},"affichage":"210 ans","explication":"2195 − 1985 = **210** ans."}]$ex$::jsonb),
  ('1c30cae9-94e2-54bc-b83f-fb92f04ce3ca'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quatre dystopies, un avertissement","competence":"analyser-document","situation":"Un tableau compare quatre romans anglophones ; un billet de blog en tire une leçon. Croise-les.","documents":[{"id":"dyst","type":"tableau","titre":"Four dystopias","colonnes":["Author","Novel","Year","The threat"],"lignes":[["Aldous Huxley","Brave New World",1932,"Happiness imposed by drugs"],["George Orwell","Nineteen Eighty-Four",1949,"Total surveillance and a poor language"],["Ray Bradbury","Fahrenheit 451",1953,"Books burned by firemen"],["Margaret Atwood","The Handmaid’s Tale",1985,"Women’s bodies controlled by a religious regime"]],"enteteLignes":false,"source":"Tableau rédigé pour l’exercice, d’après le cours"},{"id":"blog","type":"texte","genre":"article","titre":"Why do we still read dystopias?","blocs":["Dystopias do not predict the future; they warn us. Atwood has often said that nothing in her novel had not already happened somewhere in human history.","That is why these books stay alive: they take a real danger and push it to the extreme, so that we can see it clearly."],"source":"Billet imaginé pour l’exercice"}],"questions":[{"enonce":"Touche la case qui décrit la menace du roman paru en 1953.","aide":"Repère la ligne de l’année 1953.","type":"zone","document":"dyst","multiple":false},{"enonce":"Combien d’années séparent le plus ancien roman du tableau du plus récent ?","aide":"Repère la plus petite et la plus grande date.","type":"nombre","unite":"ans"},{"enonce":"Touche le verbe du billet qui résume la fonction d’une dystopie.","aide":"Il commence par « w » et ressemble au français « avertir » dans l’idée.","type":"zone","document":"blog","multiple":false},{"enonce":"Quel point commun les quatre romans du tableau partagent-ils, d’après le billet ?","aide":"Lis la phrase qui suit « That is why these books stay alive ».","type":"choix","options":[{"id":"a","texte":"Un danger réel y est poussé à l’extrême pour que le lecteur le reconnaisse"},{"id":"b","texte":"Ils imaginent tous un monde meilleur où les problèmes ont disparu"},{"id":"c","texte":"Ils racontent tous une guerre mondiale réelle, vue par un soldat"},{"id":"d","texte":"Ils sont tous écrits par des historiens qui décrivent une époque passée"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c3"]},"explication":"Le roman de 1953 est *Fahrenheit 451* : la menace, ce sont des **livres brûlés par des pompiers**."},{"cle":{"type":"nombre","valeur":53,"tolerance":0},"affichage":"53 ans","explication":"1985 − 1932 = **53** ans."},{"cle":{"type":"zone","ids":["m7"]},"explication":"Une dystopie **warns** : elle avertit, elle ne prédit pas."},{"cle":{"type":"choix","ids":["a"]},"explication":"Chaque dystopie **grossit un danger réel** (drogue, surveillance, censure, contrôle des corps) pour avertir le lecteur."}]$ex$::jsonb),
  ('1c30cae9-94e2-54bc-b83f-fb92f04ce3ca'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Offred, une voix qui résiste","competence":"analyser-texte","situation":"Un passage écrit pour l’exercice reprend la manière d’Atwood : une narratrice, des souvenirs, le danger de se souvenir. Croise-le avec la liste des personnages.","documents":[{"id":"offred","type":"texte","genre":"recit","titre":"Une chambre, une voix","blocs":["The room is small. A white curtain, a bed, a window that does not open. I am Offred now. My real name is something I whisper only at night, like a coin hidden under a tongue.","Sometimes I remember my old house, and Luke laughing, and my daughter’s shoes by the door. Then I stop. Remembering is dangerous, and it is also how I stay alive."],"source":"Texte écrit pour l’exercice, à la manière d’Atwood"},{"id":"qui","type":"tableau","titre":"Who is who?","colonnes":["Clue","Character"],"lignes":[["Her friend who tries to escape","Moira"],["Her shopping partner, linked to the resistance","Ofglen"],["The Commander’s wife, a former singer","Serena Joy"],["The man she begins a relationship with","Nick"]],"enteteLignes":false,"source":"D’après le cours"}],"questions":[{"enonce":"Touche le nom que la narratrice doit porter « maintenant ».","aide":"Le nom qui signifie « celle qui appartient à Fred ».","type":"zone","document":"offred","multiple":false},{"enonce":"Touche le prénom du mari dont elle se souvient.","aide":"Il rit dans ses souvenirs.","type":"zone","document":"offred","multiple":false},{"enonce":"Que dit la fin du passage du rôle du souvenir ?","aide":"Relis les deux dernières phrases.","type":"choix","options":[{"id":"a","texte":"Se souvenir est dangereux, mais c’est aussi ce qui la garde en vie"},{"id":"b","texte":"Se souvenir est inutile, car sa vie d’avant est oubliée pour toujours"},{"id":"c","texte":"Se souvenir est interdit, donc elle y renonce définitivement dès le premier jour"},{"id":"d","texte":"Se souvenir est sans danger, car personne ne peut l’entendre dans sa chambre"}],"multiple":false},{"enonce":"Quel effet produit un récit à la première personne et au présent ?","aide":"Que change « I » au lieu de « she », et le présent au lieu du passé ?","type":"choix","options":[{"id":"a","texte":"Le lecteur observe la scène de loin, comme un historien resté neutre"},{"id":"b","texte":"Le lecteur sait déjà comment l’histoire finit, grâce à une narratrice âgée"},{"id":"c","texte":"Le lecteur est tenu à distance par un narrateur qui dit toujours « il »"},{"id":"d","texte":"Le lecteur vit l’enfermement avec elle, sans recul ni sécurité"}],"multiple":false},{"enonce":"Associe chaque indice du document 2 au personnage correspondant.","aide":"Les indices décrivent le rôle de chacun dans l’histoire.","type":"association","gauche":[{"id":"g0","texte":"Her friend who tries to escape"},{"id":"g1","texte":"Her shopping partner, linked to the resistance"},{"id":"g2","texte":"The Commander’s wife, a former singer"},{"id":"g3","texte":"The man she begins a relationship with"}],"droite":[{"id":"d0","texte":"Moira"},{"id":"d1","texte":"Serena Joy"},{"id":"d2","texte":"Nick"},{"id":"d3","texte":"Ofglen"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m17"]},"explication":"Elle s’appelle **Offred** : son vrai nom lui a été retiré."},{"cle":{"type":"zone","ids":["m43"]},"explication":"Elle se souvient de **Luke**, son mari d’avant."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le passage joue sur deux faces : le souvenir est un **danger** et une **survie**, ce qui reflète le projet du roman (*se raconter pour survivre*)."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le « I » et le présent font vivre la scène **de l’intérieur**, sans recul d’adulte ni promesse de salut."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"**Moira** tente de s’évader, **Ofglen** appartient au réseau Mayday, **Serena Joy** est l’épouse du Commandant, **Nick** est l’homme avec qui Offred noue une liaison."}]$ex$::jsonb),
  ('6ab42e25-fe1b-5f8c-8cb9-e2cd780f2fdf'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois voix américaines","competence":"lire-tableau","situation":"Trois auteurs fondent, au XIXe siècle, l’idée d’un « moi » américain. Lis le tableau avant de répondre.","documents":[{"id":"voix","type":"tableau","titre":"The American self","colonnes":["Author","Work","Year","Idea"],"lignes":[["Walt Whitman","Song of Myself",1855,"One voice for a whole nation"],["Ralph Waldo Emerson","Self-Reliance",1841,"Trust yourself"],["Henry David Thoreau","Walden",1854,"Live alone in the woods to find yourself"]],"enteteLignes":false,"source":"D’après le cours"}],"questions":[{"enonce":"Touche la case qui donne la date de *Self-Reliance*.","aide":"Repère la ligne d’Emerson.","type":"zone","document":"voix","multiple":false},{"enonce":"Quel auteur défend l’idée « Live alone in the woods to find yourself » ?","aide":"La colonne « Idea » te donne l’indice.","type":"choix","options":[{"id":"a","texte":"Walt Whitman"},{"id":"b","texte":"Henry David Thoreau"},{"id":"c","texte":"Ralph Waldo Emerson"},{"id":"d","texte":"Langston Hughes"}],"multiple":false},{"enonce":"Range les trois œuvres de la plus ancienne à la plus récente.","aide":"Compare 1841, 1854 et 1855.","type":"ordre","items":[{"id":"a","texte":"Self-Reliance"},{"id":"b","texte":"Song of Myself"},{"id":"c","texte":"Walden"}]}]}$ex$::jsonb,
