  ('6ab42e25-fe1b-5f8c-8cb9-e2cd780f2fdf'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Dire « je » à sa manière","competence":"analyser-document","situation":"Une narratrice raconte le jour où on lui a demandé de se taire. Relie son histoire aux auteurs qui ont fait de la voix un acte politique.","documents":[{"id":"memoire","type":"texte","genre":"recit","titre":"My grandmother’s words","blocs":["When I was nine, my teacher said my way of speaking was “wrong”. At home we talked with the words of my grandmother; at school I was told to hide them.","That evening I wrote my first poem in my grandmother’s words. It was the first time the page belonged to me."],"source":"Texte écrit pour l’exercice"},{"id":"oeuvres","type":"tableau","titre":"Three books","colonnes":["Work","Year"],"lignes":[["Their Eyes Were Watching God",1937],["I Know Why the Caged Bird Sings",1969],["Beloved",1987]],"enteteLignes":false,"source":"Dates d’après le cours"}],"questions":[{"enonce":"Touche le verbe qui montre qu’on lui demandait de cacher sa langue.","aide":"Ce verbe ressemble à « cacher ».","type":"zone","document":"memoire","multiple":false},{"enonce":"Pourquoi dire « je » est-il ici un acte politique ?","aide":"Relis ce que dit l’enseignante.","type":"choix","options":[{"id":"a","texte":"Parce qu’un éditeur lui a demandé d’écrire uniquement sur la politique"},{"id":"b","texte":"Parce qu’on lui avait refusé le droit de parler avec sa propre voix"},{"id":"c","texte":"Parce qu’elle écrit contre son école et veut la voir fermée définitivement"},{"id":"d","texte":"Parce qu’elle veut devenir présidente et doit convaincre tous les électeurs"}],"multiple":false},{"enonce":"Associe chaque œuvre du document 2 à son enjeu.","aide":"Hurston, Angelou, Morrison : trois enjeux différents.","type":"association","gauche":[{"id":"g0","texte":"Their Eyes Were Watching God"},{"id":"g1","texte":"I Know Why the Caged Bird Sings"},{"id":"g2","texte":"Beloved"}],"droite":[{"id":"d0","texte":"La mémoire de l’esclavage"},{"id":"d1","texte":"La langue vernaculaire comme littérature"},{"id":"d2","texte":"Le récit de soi comme survie"}]},{"enonce":"Combien d’années séparent la plus ancienne et la plus récente des trois œuvres du document 2 ?","aide":"Repère la plus petite et la plus grande date du tableau.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
