   $ex${"titre":"Trois discours, une voix","competence":"argumenter","situation":"Une jeune fille prend la parole devant des ministres. Compare son discours à ceux de trois orateurs célèbres.","documents":[{"id":"discours","type":"texte","genre":"source","titre":"Speech to the ministers","blocs":["I am sixteen. I am not a minister. I am a girl who lost her school.","My friends are still waiting. I have the right to learn, and so do they. I speak for them."],"source":"Discours écrit pour l’exercice"},{"id":"trois","type":"tableau","titre":"Three speeches","colonnes":["Speaker","Year","What makes the speech strong"],"lignes":[["Martin Luther King",1963,"Anaphora, preaching rhythm, founding texts"],["Barack Obama",2008,"A personal story tied to the national story"],["Malala Yousafzai",2013,"Testimony as authority"]],"enteteLignes":false,"source":"D’après le cours"}],"questions":[{"enonce":"Touche les trois mots répétés qui forment l’anaphore.","aide":"La même forme verbale ouvre trois phrases de suite.","type":"zone","document":"discours","multiple":true},{"enonce":"Sur quoi repose l’autorité de cette oratrice ?","aide":"Elle dit qu’elle n’est pas ministre.","type":"choix","options":[{"id":"a","texte":"Sur la citation d’un texte religieux ou juridique connu de l’assemblée"},{"id":"b","texte":"Sur une série de chiffres et de statistiques très précis sur l’éducation"},{"id":"c","texte":"Sur son témoignage : elle parle de ce qu’elle a elle-même vécu"},{"id":"d","texte":"Sur sa fonction officielle et le titre qui l’accompagne aux yeux de tous"}],"multiple":false},{"enonce":"Associe chaque orateur du document 2 à ce qui fait la force de son discours.","aide":"Traduis la troisième colonne du tableau.","type":"association","gauche":[{"id":"g0","texte":"Martin Luther King (1963)"},{"id":"g1","texte":"Barack Obama (2008)"},{"id":"g2","texte":"Malala Yousafzai (2013)"}],"droite":[{"id":"d0","texte":"Récit personnel adossé au récit national"},{"id":"d1","texte":"Le témoignage comme autorité"},{"id":"d2","texte":"Anaphore et appel aux textes fondateurs"}]},{"enonce":"Combien d’années séparent le discours de Martin Luther King de celui de Malala Yousafzai ?","aide":"Soustrais les deux dates du tableau.","type":"nombre","unite":"ans"},{"enonce":"Quel orateur du tableau ressemble le plus à la jeune fille du document 1 ?","aide":"Compare la source de l’autorité dans les deux cas.","type":"choix","options":[{"id":"a","texte":"Aucun des trois, car ils n’emploient jamais la première personne"},{"id":"b","texte":"Malala Yousafzai, dont la force vient de ce qu’elle raconte elle-même"},{"id":"c","texte":"Barack Obama, qui lie son histoire personnelle au récit national"},{"id":"d","texte":"Martin Luther King, qui s’appuie sur les textes fondateurs du pays"}],"multiple":false}]}$ex$::jsonb,
