   $ex${"titre":"Le sonnet, par le chiffre","competence":"comprendre-langue","situation":"Une affiche présente le recueil des Sonnets de Shakespeare, et un extrait ouvre le Sonnet 18. Lis-les pour calculer et comprendre.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"SHAKESPEARE’S SONNETS","sousTitre":"First published in 1609","emoji":"📜","lignes":[{"texte":"Number of poems","valeur":"154"},{"texte":"Length of each poem","valeur":"14 lines"},{"texte":"Structure","valeur":"three quatrains and a final couplet"}],"pied":"Love, time and poetry","source":"Affiche imaginée pour l’exercice"},{"id":"s18","type":"texte","genre":"poeme","titre":"Sonnet 18","blocs":["Shall I compare thee to a summer’s day?","Thou art more lovely and more temperate:"],"source":"William Shakespeare, *Sonnets* (1609), vers 1 et 2"}],"questions":[{"enonce":"Touche le mot qui nomme ce à quoi le poète compare la personne aimée.","aide":"Il s’agit d’une saison.","type":"zone","document":"s18","multiple":false},{"enonce":"Que signifie « more lovely and more temperate » ?","aide":"« Lovely » parle du charme, « temperate » de la douceur du climat.","type":"choix","options":[{"id":"a","texte":"Plus célèbre et d’une origine plus noble"},{"id":"b","texte":"Plus brillante et d’un caractère plus fier"},{"id":"c","texte":"Plus jeune et d’une beauté plus éclatante"},{"id":"d","texte":"Plus charmante et d’un caractère plus doux"}],"multiple":false},{"enonce":"D’après l’affiche, combien de vers compte l’ensemble du recueil ?","aide":"154 poèmes, 14 vers chacun.","type":"nombre","unite":"vers"}]}$ex$::jsonb,
