   $ex${"titre":"Une émotion, puis un souvenir","competence":"analyser-texte","situation":"Wordsworth définit la poésie dans une préface, puis l’applique dans un poème. Lis les deux extraits pour comprendre sa méthode.","documents":[{"id":"nuage","type":"texte","genre":"poeme","titre":"I Wandered Lonely as a Cloud","blocs":["I wandered lonely as a cloud","That floats on high o’er vales and hills,"],"source":"William Wordsworth, « I Wandered Lonely as a Cloud » (1807), vers 1 et 2"},{"id":"preface","type":"texte","genre":"source","titre":"Une définition de la poésie","blocs":["…poetry is the spontaneous overflow of powerful feelings: it takes its origin from emotion recollected in tranquillity."],"source":"Wordsworth, préface des *Lyrical Ballads* (édition de 1800)"}],"questions":[{"enonce":"Touche le mot qui dit que l’émotion est reprise dans le calme, à distance.","aide":"C’est le dernier mot de la phrase.","type":"zone","document":"preface","multiple":false},{"enonce":"Touche le mot qui compare le poète à un élément de la nature.","aide":"C’est un nom qui flotte dans le ciel.","type":"zone","document":"nuage","multiple":false},{"enonce":"Que veut dire Wordsworth par « recollected in tranquillity » ?","aide":"« Recollected » vient de « se souvenir ».","type":"choix","options":[{"id":"a","texte":"Que l’émotion est d’abord ressentie, puis reprise calmement par le souvenir"},{"id":"b","texte":"Que le poète doit écrire dans un silence complet, sans aucune émotion"},{"id":"c","texte":"Que le poète doit recopier un souvenir dans l’ordre exact des faits"},{"id":"d","texte":"Que le poème naît au moment précis du choc, sans aucun recul"}],"multiple":false},{"enonce":"Combien d’années séparent le recueil des *Lyrical Ballads* du poème sur le nuage ?","aide":"Les deux dates sont dans les sources des documents.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
