   $ex${"titre":"Quand les mains parlent","competence":"analyser-document","situation":"Dans un film, une musicienne ne parle pas. Un passage imaginé et un tableau d’analyse montrent ce qui parle à sa place.","documents":[{"id":"scene","type":"texte","genre":"recit","titre":"A silent scene","blocs":["A close-up: Clara’s hands on the keyboard. Nothing is said. The music says it all: grief and longing.","When her brother comes in, she closes the lid and looks away."],"source":"Scène imaginée pour l’exercice, dans l’esprit de *The Piano*"},{"id":"voix","type":"tableau","titre":"What speaks instead of words","colonnes":["Element","What it does"],"lignes":[["The piano","It is Ada’s voice (music by Michael Nyman)"],["The hands","She signs, plays and writes"],["The landscape","Mud, forest, sea: a world that stifles or frees"],["Flora’s gaze","The child translates, then betrays"]],"enteteLignes":false,"source":"D’après le cours sur *The Piano* (Jane Campion, 1993)"}],"questions":[{"enonce":"Touche les deux mots qui nomment ce que ressent Clara.","aide":"Le chagrin et le désir nostalgique.","type":"zone","document":"scene","multiple":true},{"enonce":"Quel procédé de mise en scène décrit « A close-up: Clara’s hands… » ?","aide":"« Close-up » se traduit par « gros plan ».","type":"choix","options":[{"id":"a","texte":"Un gros plan : la caméra isole les mains pour montrer l’émotion"},{"id":"b","texte":"Un plan large qui montre le paysage tout entier"},{"id":"c","texte":"Une voix off : une narratrice explique ce qu’elle ressent"},{"id":"d","texte":"Un champ-contrechamp entre deux personnages qui se répondent"}],"multiple":false},{"enonce":"Dans le tableau, touche la case qui dit ce qui joue le rôle de voix d’Ada.","aide":"Cherche le mot « voice ».","type":"zone","document":"voix","multiple":false},{"enonce":"Que signifie le geste de Clara, qui « closes the lid and looks away » ?","aide":"Elle ne dit rien : que font ses gestes ?","type":"choix","options":[{"id":"a","texte":"Une surprise : elle découvre que l’instrument est cassé"},{"id":"b","texte":"Une colère violente qui la pousse à détruire son instrument"},{"id":"c","texte":"Un refus : sans parole, elle met fin à l’échange avec son frère"},{"id":"d","texte":"Un départ définitif : elle quitte la pièce et le pays"}],"multiple":false},{"enonce":"Associe chaque élément du tableau à ce qu’il exprime.","aide":"Traduis la seconde colonne.","type":"association","gauche":[{"id":"g0","texte":"The hands"},{"id":"g1","texte":"The landscape"},{"id":"g2","texte":"Flora’s gaze"}],"droite":[{"id":"d0","texte":"Un monde qui étouffe ou libère"},{"id":"d1","texte":"L’enfant traduit, puis trahit"},{"id":"d2","texte":"Elle signe, joue, écrit"}]}]}$ex$::jsonb,
