uvre, elle ne raconte pas ses préférences.","type":"choix","options":[{"id":"a","texte":"La remplacer par une citation longue du poème choisi"},{"id":"b","texte":"La supprimer car une synthèse n’en a pas besoin"},{"id":"c","texte":"La rallonger en racontant le poème qu’il a aimé"},{"id":"d","texte":"Ouvrir sur une idée tirée du dossier plutôt que donner ses goûts"}],"multiple":false}]}$ex$::jsonb,
