  ('d29170a6-b507-5a0d-abeb-bdf01882733d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un dossier de 1912","competence":"analyser-document","situation":"Voici le brouillon d’un dossier de trois documents et ses deux consignes. Prépare les liens avant d’écrire.","documents":[{"id":"dossier","type":"tableau","titre":"Le brouillon du dossier","colonnes":["Doc","Nature","Date","Ton"],"lignes":[["A","Letter from a new arrival in New York","1912","Homesick"],["B","Photograph of a crowd at the port","1912","Hopeful"],["C","Article from a local newspaper","1912","Suspicious of newcomers"]],"enteteLignes":true,"source":"Dossier imaginé pour l’exercice"},{"id":"consignes","type":"texte","genre":"consigne","titre":"Les consignes","blocs":["1. Show how newcomers feel.","2. Show how the city receives them."],"source":"Consignes imaginées pour l’exercice"}],"questions":[{"enonce":"Touche la case qui montre le point de vue hostile aux arrivants.","aide":"Cherche « suspicious ».","type":"zone","document":"dossier","multiple":false},{"enonce":"Quel lien forme-t-on en croisant les documents A et B ?","aide":"Compare la colonne « Ton » des deux documents.","type":"choix","options":[{"id":"a","texte":"A prouve que B est faux, car la lettre est plus personnelle"},{"id":"b","texte":"A et B n’ont aucun rapport et doivent être traités séparément"},{"id":"c","texte":"A et B disent exactement la même chose, donc l’un peut être ignoré"},{"id":"d","texte":"Même lieu et même date, mais la nostalgie de A contraste avec l’espoir de B"}],"multiple":false},{"enonce":"Associe chaque consigne aux documents qui y répondent le mieux.","aide":"Lettre et foule montrent des sentiments ; foule et article, l’accueil.","type":"association","gauche":[{"id":"g0","texte":"Consigne 1 : how newcomers feel"},{"id":"g1","texte":"Consigne 2 : how the city receives them"}],"droite":[{"id":"d0","texte":"Docs B et C"},{"id":"d1","texte":"Docs A et B"}]},{"enonce":"Quelle introduction est la meilleure ?","aide":"Une bonne introduction présente le dossier et pose une problématique.","type":"choix","options":[{"id":"a","texte":"Document A is a letter, document B is a photograph and document C is an article, and I will describe each in turn."},{"id":"b","texte":"In this essay, I will talk about immigration because it is an important topic and I have many ideas about it."},{"id":"c","texte":"Three documents from 1912 show how newcomers feel and how the city receives them, asking whether welcome is possible without trust."},{"id":"d","texte":"Immigration has always existed and it is a very complicated subject that many people have discussed for years."}],"multiple":false}]}$ex$::jsonb,
