  ('c493af3a-5294-5010-b7a8-92a4f2be6bb0'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Deux faux amis sur la route","competence":"comprendre-langue","situation":"Tu relis une page de roman avant de la traduire : deux mots sont des faux amis. Repère-les, puis choisis la bonne traduction.","documents":[{"id":"page","type":"texte","genre":"recit","titre":"A wrong turn","blocs":["Tom’s aunt was a sensible woman. When the bus broke down, she did not panic: she walked to the nearest farm and asked for help.","The farmer’s deception became clear later: the “short ride” he offered cost twenty pounds."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui ne veut pas dire « sensible » en français.","aide":"Pense à une femme qui garde la tête froide quand le bus tombe en panne.","type":"zone","document":"page","multiple":false},{"enonce":"Touche le mot qui désigne une tromperie, et non une déception.","aide":"Le fermier promet un trajet court, mais le prix est faux.","type":"zone","document":"page","multiple":false},{"enonce":"Comment traduire « Tom’s aunt was a sensible woman » ?","aide":"Regarde ce que fait la tante quand le bus tombe en panne.","type":"choix","options":[{"id":"a","texte":"La tante de Tom était une femme facilement émue"},{"id":"b","texte":"La tante de Tom était une femme très sensible"},{"id":"c","texte":"La tante de Tom était une femme un peu nerveuse"},{"id":"d","texte":"La tante de Tom était une femme raisonnable"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"**sensible** veut dire *raisonnable* en anglais ; pour dire « sensible » en français, on écrit *sensitive*."},{"cle":{"type":"zone","ids":["m27"]},"explication":"**deception** est la tromperie ; une déception se dit *disappointment*."},{"cle":{"type":"choix","ids":["d"]},"explication":"Elle garde son calme : **une femme raisonnable**. Le faux ami « sensible » aurait changé son caractère."}]$ex$::jsonb),
  ('c493af3a-5294-5010-b7a8-92a4f2be6bb0'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Un quai, un ferry, un passé simple","competence":"manier-langue","situation":"Tu traduis le début d’un récit. Attention au temps du verbe, à la particule et à la durée.","documents":[{"id":"ferry","type":"texte","genre":"recit","titre":"The last ferry","blocs":["When Lena reached the harbour, the ferry had already left. She stood still for a moment, then tiptoed out of the ticket office, where a guard was asleep.","“I have waited here since dawn,” she whispered."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Quelle traduction de « tiptoed out of the ticket office » respecte le chassé-croisé ?","aide":"L’anglais met le mouvement dans la particule ; le français, dans le verbe.","type":"choix","options":[{"id":"a","texte":"Elle tiptoa hors du bureau des billets en silence"},{"id":"b","texte":"Elle sortit du bureau des billets en courant sur les orteils"},{"id":"c","texte":"Elle sortit du bureau des billets, marchant sur ses orteils"},{"id":"d","texte":"Elle sortit du bureau des billets sur la pointe des pieds"}],"multiple":false},{"enonce":"Comment traduire « I have waited here since dawn » ?","aide":"Le present perfect avec « since » marque une durée qui continue.","type":"choix","options":[{"id":"a","texte":"J’attendrai ici jusqu’à l’aube"},{"id":"b","texte":"J’avais attendu ici l’aube"},{"id":"c","texte":"J’attends ici depuis l’aube"},{"id":"d","texte":"J’ai attendu ici à l’aube"}],"multiple":false},{"enonce":"Complète la traduction de la première phrase, au passé simple, comme dans un récit littéraire.","aide":"Un prétérit de récit littéraire se traduit par un passé simple.","type":"trous","segments":["Quand Lena ",0," au port, le ferry était déjà ",1,"."],"banque":["partir","arrivera","parti","arriva","arrive","partie"]}]}$ex$::jsonb,
