  ('c493af3a-5294-5010-b7a8-92a4f2be6bb0'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Trois copies, une seule bonne traduction","competence":"raisonner","situation":"Trois élèves ont traduit le même passage. Compare leurs copies avec l’original, puis rends compte du sens en quelques mots.","documents":[{"id":"passage","type":"texte","genre":"recit","titre":"The passage","blocs":["The library, a grey building at the end of the lane, was actually Eleanor’s favourite place. She came running every Saturday, and eventually the librarian gave her a key."],"source":"Texte écrit pour l’exercice"},{"id":"versions","type":"tableau","titre":"Les trois copies","colonnes":["Copie","Traduction proposée"],"lignes":[["A","La librairie, un bâtiment gris au bout du chemin, était actuellement son endroit préféré. Elle venait courant chaque samedi, et éventuellement la bibliothécaire lui donna une clé."],["B","La bibliothèque, un bâtiment gris au bout du chemin, était en fait son endroit préféré. Elle arrivait en courant chaque samedi, et la bibliothécaire finit par lui donner une clé."],["C","La bibliothèque, un bâtiment gris au bout du chemin, était en fait son endroit préféré. Elle venait courant chaque samedi, et la bibliothécaire finit par lui donner une clé."]],"enteteLignes":false,"source":"Copies imaginées pour l’exercice"}],"questions":[{"enonce":"Quelle copie est la meilleure traduction du passage ?","aide":"Cherche la copie qui évite à la fois les faux amis et le calque de la forme en -ing.","type":"choix","options":[{"id":"a","texte":"Copie B"},{"id":"b","texte":"Copie C"},{"id":"c","texte":"Copie A"}],"multiple":false},{"enonce":"Touche la copie qui traduit « actually » par un faux ami.","aide":"Le faux ami signifie « à présent ».","type":"zone","document":"versions","multiple":false},{"enonce":"Touche les deux copies qui calquent « came running » en « venait courant ».","aide":"Cherche la tournure qui sonne comme de l’anglais mot à mot.","type":"zone","document":"versions","multiple":true},{"enonce":"Quel texte est une bonne transposition du passage, en français et sans commentaire ?","aide":"Une transposition rend les idées en français, avec ses propres mots, sans juger.","type":"choix","options":[{"id":"a","texte":"Eleanor déteste la bibliothèque mais la bibliothécaire l’oblige à venir chaque samedi en lui offrant une clé."},{"id":"b","texte":"Eleanor aime la bibliothèque, ce qui prouve à quel point les enfants d’aujourd’hui manquent de loisirs intéressants."},{"id":"c","texte":"The library was actually Eleanor’s favourite place, and she came running every Saturday to see the librarian."},{"id":"d","texte":"La bibliothèque est le lieu préféré d’Eleanor, qui y court chaque samedi ; la bibliothécaire finit par lui confier une clé."}],"multiple":false}]}$ex$::jsonb,
