   $ex${"titre":"Le dossier d’Inès","competence":"analyser-document","situation":"Inès prépare son oral de LLCER sur le thème du départ. Voici la liste de son dossier.","documents":[{"id":"dossier","type":"tableau","titre":"Le dossier d’Inès","colonnes":["Document","Nature","Pays","Statut"],"lignes":[["*Brooklyn* (2009), extrait","Roman","Irlande","Œuvre intégrale étudiée"],["« The New Colossus » (1883)","Poème","États-Unis","—"],["« Migrant Mother » (1936), Dorothea Lange","Photographie","États-Unis","—"],["*Nighthawks* (1942), Edward Hopper","Peinture","États-Unis","—"],["Article sur l’émigration irlandaise","Article de presse","Irlande","Imaginé pour l’exercice"]],"enteteLignes":false,"source":"Dossier imaginé pour l’exercice"}],"questions":[{"enonce":"Touche la case qui indique l’œuvre intégrale du dossier.","aide":"Regarde la dernière colonne.","type":"zone","document":"dossier","multiple":false},{"enonce":"Combien d’œuvres d’art visuel ce dossier compte-t-il (photographie et peinture comprises) ?","aide":"Une photographie et une peinture sont des œuvres d’art visuel.","type":"nombre"},{"enonce":"Inès voudrait ajouter l’affiche d’un film. Que faut-il lui répondre ?","aide":"Une affiche est une œuvre d’art visuel.","type":"choix","options":[{"id":"a","texte":"C’est impossible : un dossier ne peut contenir ni image ni film du tout"},{"id":"b","texte":"C’est impossible : le dossier compte déjà deux œuvres d’art visuel, le maximum"},{"id":"c","texte":"C’est possible : seules les peintures sont limitées à deux dans un dossier"},{"id":"d","texte":"C’est possible : les œuvres visuelles ne sont pas limitées si elles sont anglophones"}],"multiple":false}]}$ex$::jsonb,
