  ('aa6ff3eb-9c30-549a-9fe5-b939820131fb'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le début de l’oral de Malo","competence":"argumenter","situation":"Malo ouvre son oral. Lis son introduction et repère comment il relie ses documents.","documents":[{"id":"intro","type":"texte","genre":"recit","titre":"Malo’s opening","blocs":["Good morning. My portfolio asks one question: how does leaving home change who we are?","I start from *Brooklyn*, because Eilis builds a new self abroad.","Then I turn to a poem by Heaney: unlike Eilis, the poet stays and digs where his family worked.","Finally, a photograph by Lange will show what migrants carry with them. To conclude, I will answer my question."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui annonce le contraste entre Eilis et le poète.","aide":"Il introduit une opposition entre deux personnes.","type":"zone","document":"intro","multiple":false},{"enonce":"Touche le mot qui justifie le choix de *Brooklyn* comme premier document.","aide":"Il explique le choix : « … Eilis builds a new self ».","type":"zone","document":"intro","multiple":false},{"enonce":"Remets dans l’ordre les étapes de cette introduction.","aide":"Suis les mots « Good morning », « I start », « Then », « Finally ».","type":"ordre","items":[{"id":"a","texte":"Justifier le premier document"},{"id":"b","texte":"Opposer le deuxième document au premier"},{"id":"c","texte":"Annoncer la question du dossier"},{"id":"d","texte":"Conclure en répondant à la question"}]},{"enonce":"Quelle qualité de cette introduction l’examinateur retiendra-t-il ?","aide":"Un dossier n’est pas une collection : il répond à une question.","type":"choix","options":[{"id":"a","texte":"Chaque document est décrit en détail, sans aucun lien avec les autres"},{"id":"b","texte":"Les documents s’enchaînent selon une logique annoncée dès la première phrase"},{"id":"c","texte":"La question n’apparaît qu’à la fin, une fois tous les documents vus"},{"id":"d","texte":"Le candidat lit d’abord un long résumé de toute l’œuvre intégrale"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m34"]},"explication":"**unlike** oppose Eilis, qui part, au poète, qui reste : c’est la logique du dossier."},{"cle":{"type":"zone","ids":["m19"]},"explication":"**because** justifie le choix : un candidat doit toujours rendre compte de ses documents."},{"cle":{"type":"ordre","ids":["c","a","b","d"]},"explication":"Problématique, premier document, contraste, conclusion : **l’enchaînement est annoncé**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le dossier est **un tout construit autour d’une question** annoncée d’entrée."}]$ex$::jsonb),
  ('aa6ff3eb-9c30-549a-9fe5-b939820131fb'::uuid, 3, 3, 15, 50, 3,
   $ex${"titre":"Quel dossier tient debout ?","competence":"argumenter","situation":"Sacha et Noa présentent leur dossier. Compare-les comme le ferait l’examinateur.","documents":[{"id":"sacha","type":"tableau","titre":"Dossier de Sacha — How do borders shape who we are?","colonnes":["Document","Nature","Origine"],"lignes":[["*Americanah* (2013), extrait","Roman","Nigeria, États-Unis"],["« Mending Wall » (1914), Robert Frost","Poème","États-Unis"],["« The New Colossus » (1883)","Poème","États-Unis"],["Photographie du mur américano-mexicain","Photographie","États-Unis"],["*L’Étranger* (1942), Albert Camus, extrait","Roman (en français)","France"]],"enteteLignes":false,"source":"Dossier imaginé pour l’exercice"},{"id":"noa","type":"tableau","titre":"Dossier de Noa — aucune question posée","colonnes":["Document","Nature","Origine"],"lignes":[["*Much Ado About Nothing* (1993), extrait","Film","Royaume-Uni"],["Une chanson qu’elle adore","Chanson","Royaume-Uni"],["*Pride and Prejudice* (1813), extrait","Roman","Royaume-Uni"],["Une affiche de série","Affiche","États-Unis"]],"enteteLignes":false,"source":"Dossier imaginé pour l’exercice"}],"questions":[{"enonce":"Touche la case qui montre qu’un document sort du monde anglophone.","aide":"Tous les documents doivent venir du monde anglophone.","type":"zone","document":"sacha","multiple":false},{"enonce":"Quel dossier a la cohésion que l’examinateur attend ?","aide":"Qu’est-ce qui fait l’unité d’un dossier ?","type":"choix","options":[{"id":"a","texte":"Celui de Noa, car elle aime chacun de ses documents sincèrement"},{"id":"b","texte":"Celui de Sacha, car une question rassemble ses documents"},{"id":"c","texte":"Celui de Noa, car il contient un film et une affiche récents"},{"id":"d","texte":"Les deux, car chacun compte au moins quatre documents"}],"multiple":false},{"enonce":"L’examinateur demande à Sacha : « Why do you put Frost’s poem before the photograph? » Quelle réponse est la meilleure ?","aide":"Une bonne réponse relie le choix à la question du dossier.","type":"choix","options":[{"id":"a","texte":"Because the poem is older than the photograph, and old documents always come first."},{"id":"b","texte":"Because my teacher suggested the order and I did not think about it much myself."},{"id":"c","texte":"Because I prefer poems to photographs, so I wanted to start with the one I like best."},{"id":"d","texte":"Because Frost’s wall is a metaphor for division, and the photograph makes the same idea literal."}],"multiple":false}]}$ex$::jsonb,
