   $ex${"titre":"Lire un plan de film","competence":"analyser-document","situation":"Un court métrage (imaginé pour l’exercice) se passe dans une cour de prison. Croise la liste des plans et la note d’un critique.","documents":[{"id":"plans","type":"tableau","titre":"Shot list — The Yard","colonnes":["Shot","Shot type","Camera angle","Sound"],"lignes":[["1","Long shot","Eye level","Wind"],["2","Close-up","Eye level","Voice-over"],["3","Medium shot","Low angle","Footsteps"],["4","Medium shot","High angle","Silence"]],"enteteLignes":false,"source":"Liste de plans imaginée pour l’exercice"},{"id":"note","type":"texte","genre":"article","titre":"Critic’s note","blocs":["The director lets the camera decide who holds power. The guard appears from below, tall against the sky. Sam, in the last shot, is filmed from above and left alone with the silence.","In the second shot, a voice-over gives us access to Sam’s thoughts, which he never says aloud."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche la case qui indique la contre-plongée (a low-angle shot).","aide":"La caméra est placée en dessous du garde.","type":"zone","document":"plans","multiple":false},{"enonce":"Quel numéro de plan contient la voix off dont parle le critique ?","aide":"Cherche la colonne « Sound ».","type":"nombre"},{"enonce":"Complète la phrase d’analyse.","aide":"Une plongée écrase le personnage.","type":"trous","segments":["A ",0," shot shows Sam from above, so he looks ",1,"."],"banque":["low-angle","high-angle","small","powerful"]},{"enonce":"Quelle phrase interprète ensemble les plans 3 et 4 ?","aide":"Associe chaque angle à l’effet qu’il produit.","type":"choix","options":[{"id":"a","texte":"The contrast between the low and high angles conveys who holds power and who is diminished."},{"id":"b","texte":"The silence in the last shot implies that Sam has escaped from the prison yard."},{"id":"c","texte":"The two angles suggest that the guard and Sam are equally powerful in the yard."},{"id":"d","texte":"The high angle makes the guard look tall, while the low angle shows Sam’s courage."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c2"]},"explication":"**Low angle** = contre-plongée : elle grandit le garde."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"Le plan **2** a la voix off, qui donne accès aux pensées de Sam."},{"cle":{"type":"trous","trous":[["high angle"],["small"]]},"affichage":"high-angle · small","explication":"Une **plongée** (high-angle shot) rend Sam **small** : il est écrasé par le décor."},{"cle":{"type":"choix","ids":["a"]},"explication":"La première phrase **relie les angles au pouvoir** : le garde domine, Sam est diminué."}]$ex$::jsonb),
