  ('5bebdf5b-9432-5b85-870a-0c3f83dfcab2'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Melting pot ou salad bowl ?","competence":"analyser-texte","situation":"Une professeure présente deux images de la société américaine. Lis son intervention, puis classe des phrases.","documents":[{"id":"prof","type":"texte","genre":"article","titre":"A teacher’s talk","blocs":["Some people say a country is a melting pot: newcomers must give up their old habits and become one people.","I prefer the image of a salad bowl. Here, each community keeps its own festivals and its own language, and the differences make the dish richer."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot de la première image qui suppose que tout se fond dans un alliage commun.","aide":"Pense au métal qui fond dans un récipient.","type":"zone","document":"prof","multiple":false},{"enonce":"Quelle image la professeure préfère-t-elle, et pourquoi ?","aide":"Relis la phrase qui commence par « I prefer ».","type":"choix","options":[{"id":"a","texte":"Le salad bowl, car les différences enrichissent le plat"},{"id":"b","texte":"Le salad bowl, car chaque communauté doit se fondre dans la salade"},{"id":"c","texte":"Le melting pot, car chaque culture garde sa saveur dans l’alliage"},{"id":"d","texte":"Le melting pot, car les différences finissent par disparaître"}],"multiple":false},{"enonce":"Classe chaque phrase selon l’image qu’elle illustre.","aide":"Demande-toi si la phrase efface la différence ou la garde.","type":"categories","categories":[{"id":"c0","texte":"Melting pot"},{"id":"c1","texte":"Salad bowl"}],"items":[{"id":"i0","texte":"Assimilation is the price of entry."},{"id":"i1","texte":"Belonging does not require sameness."},{"id":"i2","texte":"Differences make the whole richer."},{"id":"i3","texte":"Each community keeps its own festivals."},{"id":"i4","texte":"One shared identity replaces many."},{"id":"i5","texte":"Newcomers are expected to drop their old habits."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7"]},"explication":"**melting** : dans le *melting pot*, tout fond ensemble et l’assimilation est la condition d’entrée."},{"cle":{"type":"choix","ids":["a"]},"explication":"Elle préfère le **salad bowl** : la différence n’empêche pas l’appartenance."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c1","i4":"c0","i5":"c0"}},"explication":"Le melting pot **efface** les différences ; le salad bowl les **garde**."}]$ex$::jsonb),
  ('5bebdf5b-9432-5b85-870a-0c3f83dfcab2'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un citoyen à qui l’on demande ses papiers","competence":"raisonner","situation":"Voici trois frontières d’aujourd’hui, puis une histoire inventée inspirée du scandale Windrush. Croise les deux documents.","documents":[{"id":"front","type":"tableau","titre":"Three borders","colonnes":["Case","Type of border","What it shows"],"lignes":[["The Mexican wall","Physical and political device","A border you can see"],["Brexit and Ireland","An invisible line that becomes a problem again","A border you cannot see but can feel"],["The Windrush generation","Legal status","Citizens made illegal afterwards"]],"enteteLignes":false,"source":"D’après le cours"},{"id":"clarke","type":"texte","genre":"recit","titre":"Mr Clarke’s letter","blocs":["Mr Clarke came to Britain as a child in 1960, on his mother’s passport. He worked, paid taxes and raised three children.","In 2018 a letter asked him to prove his right to stay with documents he had never been given. At the pharmacy, a neighbour asked him, kindly, where he was “really” from."],"source":"Histoire imaginée pour l’exercice, inspirée du scandale Windrush"}],"questions":[{"enonce":"Quelle ligne du tableau l’histoire de Mr Clarke illustre-t-elle ?","aide":"Mr Clarke est arrivé légalement, puis on lui a demandé de prouver son droit de rester.","type":"choix","options":[{"id":"a","texte":"Aucune : Mr Clarke n’est concerné par aucune frontière"},{"id":"b","texte":"Le Brexit : une frontière invisible redevenue un problème"},{"id":"c","texte":"Le mur mexicain : une frontière physique et politique"},{"id":"d","texte":"La génération Windrush : des citoyens rendus illégaux après coup"}],"multiple":false},{"enonce":"Touche le mot qui montre que son droit de rester dépend de papiers.","aide":"La lettre lui demande de prouver quelque chose.","type":"zone","document":"clarke","multiple":false},{"enonce":"Classe ces deux faits selon la nature de la frontière qu’ils révèlent.","aide":"Une lettre officielle relève du droit ; une question « gentille » relève du regard des autres.","type":"categories","categories":[{"id":"c0","texte":"Dispositif juridique"},{"id":"c1","texte":"Imaginaire"}],"items":[{"id":"i0","texte":"A letter asks him to prove his right to stay."},{"id":"i1","texte":"A neighbour asks where he is really from."},{"id":"i2","texte":"People see him as a foreigner in his own street."},{"id":"i3","texte":"He must present papers he was never given."}]},{"enonce":"En quoi cette histoire montre-t-elle qu’une frontière peut bouger sans que la carte change ?","aide":"Qu’est-ce qui change dans la vie de Mr Clarke entre 1960 et 2018 ?","type":"choix","options":[{"id":"a","texte":"Mr Clarke n’a pas bougé, mais son droit de rester a changé du jour au lendemain"},{"id":"b","texte":"Le gouvernement a déplacé la frontière maritime entre les deux pays voisins"},{"id":"c","texte":"Mr Clarke a franchi une nouvelle frontière physique pour rentrer chez lui"},{"id":"d","texte":"La carte du Royaume-Uni a été redessinée en 2018 à cause de lui seul"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"Mr Clarke illustre **la génération Windrush** : son statut légal a été remis en cause après des décennies."},{"cle":{"type":"zone","ids":["m35"]},"explication":"**documents** : la frontière est ici un dispositif juridique."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0"}},"explication":"Une frontière est à la fois un **dispositif juridique** (lettre, papiers) et un **imaginaire** (le regard des voisins)."},{"cle":{"type":"choix","ids":["a"]},"explication":"La frontière est ici **juridique et mentale** : le lieu est le même, le droit a changé."}]$ex$::jsonb),
