   $ex${"titre":"Sans loyer, sans nom, vers l’Ouest","competence":"analyser-texte","situation":"Un passage écrit pour l’exercice, dans l’esprit de *Moon Palace* (ce n’est pas un extrait du roman), met en scène un narrateur qui perd tout puis se met en route.","documents":[{"id":"nuit","type":"texte","genre":"recit","titre":"Out of money","blocs":["The month I sold the last of my uncle’s books, I stopped paying rent. I slept in the park, under a bench, and watched the moon climb over the towers. Nobody knew my name.","One morning I set off west on foot, wondering whether I was running away or looking for something."],"source":"Texte écrit pour l’exercice, dans l’esprit de *Moon Palace*"}],"questions":[{"enonce":"Touche le mot qui montre que le narrateur ne sait pas pourquoi il part.","aide":"Il hésite entre deux raisons.","type":"zone","document":"nuit","multiple":false},{"enonce":"Selon la méthode du cours, quel est le motif de son départ ?","aide":"Regarde ce qu’il a perdu avant de partir.","type":"choix","options":[{"id":"a","texte":"Il part rejoindre un proche qui l’attend à l’autre bout du pays depuis des mois"},{"id":"b","texte":"Il part en mission, avec un itinéraire précis et un but clairement fixé à l’avance"},{"id":"c","texte":"Il part en vacances, pour le plaisir de découvrir des paysages nouveaux et célèbres"},{"id":"d","texte":"Il part par nécessité après avoir tout perdu, sans savoir s’il fuit ou s’il cherche"}],"multiple":false},{"enonce":"Que signifie « to set off » dans « I set off west on foot » ?","aide":"Pense au verbe français qui marque le début d’un voyage.","type":"choix","options":[{"id":"a","texte":"Se mettre à genoux"},{"id":"b","texte":"S’éloigner de la foule"},{"id":"c","texte":"Partir en retard"},{"id":"d","texte":"Se mettre en route"}],"multiple":false}]}$ex$::jsonb,
