   $ex${"titre":"Une plume à la place d’une charrue","competence":"analyser-texte","situation":"Ce poème, écrit pour l’exercice dans l’esprit de « Digging » de Seamus Heaney, parle d’héritage. Lis-le et observe ce qu’il garde et ce qu’il change.","documents":[{"id":"poeme","type":"texte","genre":"poeme","titre":"A pencil for a plough","blocs":["My grandfather ploughed the stony hill,","my father mended its wall.","I own no field, but I have, still,","a pencil, a voice, and their names. That is all."],"source":"Poème écrit pour l’exercice, dans l’esprit de « Digging » (ce n’est pas le poème de Heaney)"}],"questions":[{"enonce":"Touche l’outil que le poète utilise à la place de la charrue.","aide":"Il sert à écrire.","type":"zone","document":"poeme","multiple":false},{"enonce":"Que dit ce poème de l’héritage ?","aide":"L’héritage n’est pas imité, il est transformé.","type":"choix","options":[{"id":"a","texte":"Le poète imite exactement le travail de ses ancêtres, sans rien changer à leurs gestes"},{"id":"b","texte":"Le poète rejette son passé et préfère oublier le nom de sa famille entière"},{"id":"c","texte":"Le poète ne copie pas ses ancêtres : il prolonge leur travail avec un autre outil"},{"id":"d","texte":"Le poète regrette d’avoir hérité d’un champ qu’il n’a jamais voulu cultiver"}],"multiple":false},{"enonce":"Classe chaque élément : reçu des ancêtres ou transformé par le poète ?","aide":"Les ancêtres travaillent la terre ; le poète écrit.","type":"categories","categories":[{"id":"c0","texte":"Reçu des ancêtres"},{"id":"c1","texte":"Transformé par le poète"}],"items":[{"id":"i0","texte":"mending the wall"},{"id":"i1","texte":"giving a voice to the family’s names"},{"id":"i2","texte":"ploughing the stony hill"},{"id":"i3","texte":"writing with a pencil"}]}]}$ex$::jsonb,
